E["item:alterac-signet-ring"] = {t="item",n="Alterac Signet Ring",z="alterac",s="An Alterac Signet Ring marks a Syndicate member as one of the former nobles behind the gang. Magistrate Maleb in Southshore seeks these rings to weaken the Syndicate's leadership.",h="An Alterac Signet Ring marks a Syndicate member as one of the former nobles behind the gang.",sec={{t="A Noble's Mark",b="In the ruins of Strahnbrad, Alterac Signet Rings mark Syndicate agents who once belonged to Alterac's nobility. Magistrate Maleb in Southshore wants them gathered. He fears the Syndicate's leaders mean to ruin the town, and believes stripping them of their rings will leave the gang unable to act with purpose.",sp=0}},faq={{q="What is an Alterac Signet Ring?",a="An Alterac Signet Ring is worn by a Syndicate agent who is one of the gang's former nobles.",al={"alterac ring","syndicate signet","what's the ring"}},{q="Who wants these rings?",a="Magistrate Maleb in Southshore wants the rings to weaken the Syndicate's leadership.",al={"who wants ring","maleb rings","where bring signets"}},{q="Where can I find the rings?",a="Syndicate members in Alterac Mountains carry Alterac Signet Rings, and the ruins of Strahnbrad are thought to be the gang's headquarters.",al={"ring location","where signet rings","get alterac ring"}},{q="Why does Maleb want the rings?",a="Magistrate Maleb believes removing the Syndicate's former nobles will leave the gang unable to act decisively.",al={"why rings","maleb's plan","why collect signets"}}},ang={["faction:Alliance"]="As an Alliance traveler, Maleb asks you to help protect Southshore by weakening the Syndicate's leadership."},kw={"alterac","alterac signet ring","magistrate maleb","nobility","noble","southshore","strahnbrad","syndicate"},rel={"quest:512","zone:alterac"},src={"Wowpedia: Alterac Signet Ring","Noble Deaths"}}
E["item:cleverly-encrypted-letter"] = {t="item",n="Cleverly Encrypted Letter",z="alterac",s="The Cleverly Encrypted Letter is an unreadable note found in Hillsbrad Foothills. Loremaster Dibbs sends it onward to Prospector Stormpike in Ironforge, hoping his expertise can reveal its meaning.",h="The Cleverly Encrypted Letter is an unreadable note found in Hillsbrad Foothills.",sec={{t="An Unreadable Note",b="On a table in Hillsbrad Foothills, one letter stands apart from the rest. Its writing is encrypted and inscrutable, so you bring it to Loremaster Dibbs in Southshore. He has never seen this form of encryption and doubts his own knowledge is enough. He sends you to his colleague Prospector Stormpike in Ironforge, a specialist in such puzzles.",sp=0}},faq={{q="Where did the letter come from?",a="The letter was found among other letters on a table in Hillsbrad Foothills.",al={"letter origin","where found","encrypted note"}},{q="Why is the letter encrypted?",a="Its writing uses a form of encryption that Loremaster Dibbs has never seen. Its purpose is not known.",al={"why encrypted","what's the code","letter code"}},{q="Who is trying to read the letter?",a="Loremaster Dibbs in Southshore examines the letter, then sends you to his colleague Prospector Stormpike in Ironforge.",al={"who deciphers it","who can read it","letter reader"}},{q="Where can I take the letter?",a="Take the letter to Prospector Stormpike in the Library of Ironforge's Hall of Explorers. Loremaster Dibbs sent you.",al={"where take letter","letter to stormpike","who do i show"}}},ang={["faction:Alliance"]="As an Alliance traveler, you carry the letter from Southshore to Ironforge, linking two settlements where scholars may help uncover its meaning."},kw={"cleverly encrypted letter","encrypted letter","hall of explorers","ironforge","letter","loremaster dibbs","prospector stormpike","southshore"},rel={"quest:511","quest:514","npc:prospector-stormpike","subzone:southshore","subzone:hall-of-explorers","zone:hillsbrad","zone:ironforge"},src={"Cleverly Encrypted Letter","Encrypted Letter (Hillsbrad Foothills)","Letter to Stormpike"}}
E["item:decrypted-letter"] = {t="item",n="Decrypted Letter",z="alterac",s="The Decrypted Letter is a cryptic message found among Syndicate thieves in the Alterac foothills. Magistrate Maleb in Southshore sees reason to fear that the thieves answer to another power.",h="The Decrypted Letter is a cryptic message found among Syndicate thieves in the Alterac foothills.",sec={{t="A Strange Message",b="The foothills of Alterac hold more than thieves: the Decrypted Letter found in a Syndicate encampment troubles Magistrate Maleb of Southshore. Its words are cryptic, and Maleb recognizes that neither a thief nor an Alterac noble wrote them. He suspects the Syndicate has ties to another power, though the letter leaves him dreading what that might be.",sp=0}},faq={{q="Where was the Decrypted Letter found?",a="The Decrypted Letter was found in a Syndicate encampment in the Alterac foothills.",al={"where found","letter location","syndicate letter"}},{q="Who should receive the letter?",a="Magistrate Maleb in Southshore should receive the Decrypted Letter.",al={"who gets it","take letter where","magistrate maleb"}},{q="What does Maleb make of the letter?",a="Maleb says the letter was written by neither a thief nor an Alterac noble. He suspects the Syndicate has ties to another power.",al={"what does it say","maleb's reaction","cryptic letter meaning"}},{q="Who wrote the letter?",a="Maleb says the letter was written by neither a thief nor an Alterac noble; its author remains unknown.",al={"letter author","who sent it","not a thief"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can bring the message from the Alterac foothills to Magistrate Maleb in Southshore, where he can judge the threat."},kw={"alterac foothills","cryptic message","decrypted letter","further mysteries","magistrate maleb","southshore","syndicate"},rel={"quest:525","topic:syndicate","subzone:southshore","zone:alterac"},src={"Wowpedia: Decrypted Letter","Further Mysteries"}}
E["item:dirty-knucklebones"] = {t="item",n="Dirty Knucklebones",z="alterac",s="Dirty Knucklebones are carried by Crushridge ogres in the Alterac Mountains. Marshal Redpath in Southshore pays a bounty for them to keep the ogres from threatening the foothills.",h="Dirty Knucklebones are carried by Crushridge ogres in the Alterac Mountains.",sec={{t="A Marshal’s Bounty",b="Marshal Redpath asks for Dirty Knucklebones from the Crushridge ogres near the ruined city of Alterac. He fears the ogres may press down into the foothills if they feel secure in the ruins. The bones he gathers are meant to keep them away from Southshore, at least for a while.",sp=0}},faq={{q="Who carries Dirty Knucklebones?",a="Crushridge ogres in the Alterac Mountains carry Dirty Knucklebones.",al={"who has knucklebones","which ogres carry them"}},{q="Why does Marshal Redpath want them?",a="Marshal Redpath pays a bounty for the bones to discourage the Crushridge ogres from moving down into the foothills.",al={"why knucklebones","what are they for"}},{q="Where do I bring Dirty Knucklebones?",a="Bring Dirty Knucklebones to Marshal Redpath in Southshore.",al={"where to take bones","redpath knucklebones"}},{q="Where are the Crushridge ogres?",a="The Crushridge ogres have an ogre mound in the Alterac Mountains near the ruined city of Alterac.",al={"crushridge location","ogres in alterac"}}},kw={"alterac mountains","bounty","crushridge","dirty knucklebones","marshal redpath","ogres","southshore"},rel={"quest:500","zone:alterac","subzone:southshore","quest:504"},src={"Wowpedia: Dirty Knucklebones","Crushridge Bounty"}}
E["item:head-of-baron-vardus"] = {t="item",n="Head of Baron Vardus",z="alterac",s="Baron Vardus’s severed head is proof of Southshore’s hunt for the former Alterac noble. Magistrate Maleb seeks justice for the brutality visited upon the town.",h="Baron Vardus’s severed head is proof of Southshore’s hunt for the former Alterac noble.",sec={{t="A Baron Brought Low",b="The contract bearing Baron Vardus’s name leads from Southshore into the Syndicate haunts of Alterac. Vardus is a noble of the former kingdom, known for a cold heart and brutal practices. Magistrate Maleb wants him brought to justice after his thugs were sent against Southshore. The Baron’s head is the proof Maleb demands.",sp=0}},faq={{q="Who was Baron Vardus?",a="Baron Vardus was a noble of the former kingdom of Alterac, known for his cold heart and brutal practices.",al={"who's vardus","baron vardus","vardus backstory"}},{q="Why does Southshore want his head?",a="Magistrate Maleb says Vardus sent his thugs against Southshore and wants him brought to justice.",al={"why kill vardus","southshore wants vardus","vardus wanted"}},{q="Where can Baron Vardus be found?",a="Vardus is among the Syndicate haunts in Alterac, perhaps at the ruins of Strahnbrad or in the valley north of them.",al={"where is vardus","vardus location","find baron"}},{q="Who receives the head?",a="Magistrate Maleb in Southshore receives Baron Vardus’s head as proof that the hunt is done.",al={"who wants the head","head for maleb","vardus head"},sp=1}},ang={["faction:Alliance"]="As an Alliance traveler, you can see Southshore seeking justice against a Syndicate noble who sent thugs against the town."},kw={"alterac","baron vardus","head of baron vardus","magistrate maleb","southshore","strahnbrad","syndicate"},rel={"quest:523","quest:522","quest:566","topic:syndicate","subzone:strahnbrad","subzone:southshore","zone:alterac","topic:alterac-kingdom"},src={"Wowpedia: Head of Baron Vardus","Baron's Demise"}}
E["item:head-of-nagaz"] = {t="item",n="Head of Nagaz",z="alterac",s="Nagaz’s head is proof that Magistrate Maleb’s search in the Alterac Mountains reached the Argus Wake. Maleb fears the group, allied with the Syndicate, is a threat.",h="Nagaz’s head is proof that Magistrate Maleb’s search in the Alterac Mountains reached the Argus Wake.",sec={{t="Proof for Maleb",b="In the Uplands north of Strahnbrad, Nagaz leads the Argus Shadow Mages named in a letter brought to Magistrate Maleb. Maleb suspects the Argus Wake has joined forces with the Syndicate. Nagaz’s head gives Southshore proof that the envoys have been found.",sp=0}},faq={{q="Who was Nagaz?",a="Nagaz was a member of the Argus Wake and led Argus Shadow Mages in the Uplands.",al={"who is nagaz","nagaz guy"}},{q="Where can I find Nagaz?",a="Nagaz is in the Uplands of the Alterac Mountains, north of Strahnbrad.",al={"nagaz location","where nagaz"}},{q="Why does Magistrate Maleb want Nagaz’s head?",a="Magistrate Maleb wants proof that Nagaz and the Argus Shadow Mages are in the Uplands, where the Syndicate is strongest. He fears the Argus Wake, in alliance with the Syndicate, is a threat.",al={"why head of nagaz","maleb wants head"}},{q="What is the Argus Wake?",a="The Argus Wake is a group whose member Nagaz wrote to the Syndicate. Maleb fears its alliance with the Syndicate may pose a threat.",al={"argus wake meaning","who are argus wake"}},{q="What are the Argus Shadow Mages doing?",a="The Argus Shadow Mages are envoys of the Argus Wake found alongside Nagaz in the Uplands.",al={"argus mages","shadow mages"}}},ang={["faction:Alliance"]="As an Alliance traveler, you carry Magistrate Maleb’s concern from Southshore into the Uplands, where the Syndicate is strongest."},kw={"alterac mountains","argus shadow mages","argus wake","dark council","head of nagaz","nagaz","southshore","strahnbrad","syndicate","uplands"},rel={"quest:537","topic:syndicate","zone:alterac","subzone:uplands","subzone:strahnbrad","subzone:southshore","topic:alliance"},src={"Wowpedia: Head of Nagaz","Dark Council"}}
E["npc:archmage-ansirem-runeweaver"] = {t="npc",n="Archmage Ansirem Runeweaver",z="alterac",s="At the Violet Citadel, Archmage Ansirem Runeweaver oversees Kirin Tor work as Dalaran is rebuilt. A senior human wizard on the Council of Six, he survived the Scourge's destruction of the city. His willful daughter ran off to Booty Bay to become a pirate.",h="At the Violet Citadel, Archmage Ansirem Runeweaver oversees Kirin Tor work as Dalaran is rebuilt.",sec={{t="A Pillar of the Kirin Tor",b="Ansirem Runeweaver helped defend Dalaran for decades. He holds a seat on the Council of Six, which rules the Kirin Tor. He survived when Arthas Menethil and the Scourge marched on the city and Archimonde was summoned. After Dalaran fell, Ansirem joined the effort to rebuild it. The protective shield came down early, and he now works from the Violet Citadel.",sp=0},{t="Far-Flung Interests",b="Ansirem's ties reach beyond the Alterac Mountains. His willful daughter, Catelyn, ran off to Booty Bay to become a pirate, taking an ancient troll dagger he found while researching in Stranglethorn. Ansirem has dealt with Baron Revilgaz there. He has also studied troll antiquities and keeps diplomatic conduits open across distant realms.",sp=0}},faq={{q="Who is Archmage Ansirem Runeweaver?",a="Ansirem is an accomplished human wizard and one of the six ruling archmages on the Kirin Tor's Council of Six. After decades defending Dalaran, he now oversees work around the rebuilt city and its arcane perimeter.",al={"who is ansirem","ansirem runeweaver lore","who is the archmage"}},{q="What happened to his daughter?",a="Ansirem's willful daughter, Catelyn, ran off to Booty Bay to become a pirate, where she is known as Catelyn the Blade. She took an ancient troll dagger that Ansirem found while researching in Stranglethorn.",al={"ansirem daughter","catelyn the blade","catelyn runeweaver"}},{q="What is his role in Dalaran?",a="Ansirem is a leading Kirin Tor presence in the Violet Citadel. He coordinates research, magical defense and communication with allies as Dalaran is rebuilt after the Third War's destruction.",al={"why is ansirem in alterac","ansirem dalaran","what is he doing here"}},{q="Did Ansirem fight in the Third War?",a="Yes. Ansirem helped defend Dalaran for decades and survived the Scourge's siege. Arthas guarded Kel'Thuzad's summoning of Archimonde. Ansirem lived through the city's destruction and now helps rebuild it.",al={"ansirem scourge","did ansirem fight arthas"}}},ang={["class:Mage"]="As a Mage, you can look to Ansirem, a revered member of the Council of Six, for guidance in disciplined arcane study.",["faction:Alliance"]="As an Alliance member, you share interests with Ansirem, a Kirin Tor leader based in Lordaeron. Human spellcasters struggle to reclaim their lands from Scourge remnants."},kw={"ansirem","booty bay","catelyn","council of six","dalaran","violet citadel","kirin tor","revilgaz","runeweaver"},rel={"subzone:dalaran","zone:alterac","subzone:booty-bay","npc:baron-revilgaz","topic:third-war","topic:arthas-menethil","topic:alliance"},src={"Archmage Ansirem Runeweaver"}}
E["npc:bath-rah-the-windwatcher"] = {t="npc",n="Bath'rah the Windwatcher",z="alterac",s="Near Chillwind Point, Bath'rah the Windwatcher studies the northern winds in the Alterac Mountains. Far from his tropical homeland, the jungle troll shaman seeks champions strong enough to shape the tempest into weapons.",h="Near Chillwind Point, Bath'rah the Windwatcher studies the northern winds in the Alterac Mountains.",sec={{t="Hermit of the Peaks",b="Bath'rah the Windwatcher keeps to the cold ruins of the Alterac Mountains. Jungle trolls usually dwell among warm forests and coasts, far from these peaks. A seasoned shaman and craftsman, he listens to the wind and communes with nature spirits. He means to bind violent storms into weapons for those strong enough to wield them.",sp=0},{t="Master of Cyclonian",b="Cyclonian is a monstrous wind elemental in the peaks around Bath'rah. He cannot defeat it alone, so he calls on seasoned warriors and shamans to gather exotic elemental essences and summon the creature. When Cyclonian is slain, Bath'rah claims its elemental heart. He uses it to make legendary weapons of raw tempest, renowned across Azeroth.",sp=1}},faq={{q="Who is Bath'rah the Windwatcher?",a="Bath'rah is a jungle troll shaman and weaponcrafter living in seclusion among ruins near Chillwind Point in the Alterac Mountains. He helps seasoned adventurers harness elemental power in weapons.",al={"bathrah identity","who is bathrah","windwatcher lore"},it="identity"},{q="Why is a jungle troll living in Alterac?",a="Bath'rah lives as a hermit near Chillwind Point, studying elemental power and helping capable adventurers forge weapons. The reason he left his homeland is not established.",al={"why is bathrah in alterac","troll in alterac mountains"},it="why_here"},{q="What is Cyclonian?",a="Cyclonian is a massive, violent wind elemental haunting the ruins around Bath'rah's sanctuary. Bath'rah needs its core to forge weapons infused with elemental wind.",al={"who is cyclonian","what does bathrah summon"},it="target"},{q="Why do warriors seek him out?",a="Warriors travel from across the world to Bath'rah because he knows how to forge the Whirlwind weapons. Under his guidance, defeating Cyclonian yields arms infused with howling gales.",al={"bathrah warrior quest","whirlwind axe guy"},it="purpose"},{q="Does Bath'rah only help members of the Horde?",a="Bath'rah lives apart from major faction politics as a solitary hermit. He focuses on elemental craft and helps capable warriors and shamans who respect the spirits and aid his elemental work.",al={"is bathrah hostile","bathrah alliance"},it="side"},{q="What does Bath'rah the Windwatcher want?",a="Bath'rah seeks a worthy champion capable of confronting and defeating Cyclonian, a raging elemental residing near his camp. He covets the creature's heart, hoping to harness its raw primordial energy to forge an extraordinary weapon of immense power.",al={"bath'rah wants","what does bathrah want","bathrah goal"},it="wants",add="4f68ea16"}},ang={["class:Warrior"]="Veteran fighters know Bath'rah for guiding them through the trials to forge Whirlwind weapons with the essence of Cyclonian, the wind elemental.",["class:Shaman"]="As a fellow master of the elements, Bath'rah shares a deep spiritual connection with shamans seeking closer communion with the spirits of earth, water, and air."},kw={"alterac","bath'rah","chillwind","cyclonian","elemental","shaman","whirlwind","windwatcher"},rel={"subzone:chillwind-point","zone:alterac","quest:1791","topic:troll"},src={"Bath'rah the Windwatcher"}}
E["npc:lieutenant-haggerdin"] = {t="npc",n="Lieutenant Haggerdin",z="alterac",s="At the Headland gate, Lieutenant Haggerdin gathers recruits for the Stormpike Guard. He watches the entrance to Alterac Valley and honors Alliance champions who prove their valor against the Frostwolf Clan.",h="At the Headland gate, Lieutenant Haggerdin gathers recruits for the Stormpike Guard.",sec={{t="Gatekeeper of the Headland",b="At the snowy Headland above the Hillsbrad Foothills, Lieutenant Haggerdin oversees the Alliance muster for its campaign in Alterac Valley. Dwarven banners mark the massive wooden gate. Recruits and veterans gather under his watch before entering the frigid warzone.",sp=0},{t="Voice of the Stormpike Guard",b="Lieutenant Haggerdin serves the Stormpike Expedition, testing warriors who would represent Ironforge and the Grand Alliance in the valley. In trials such as the Proving Grounds, recruits recover banners and relics. As soldiers rise through the Stormpike Guard, Haggerdin grants official commendations, insignias, and rank recognitions.",sp=0}},faq={{q="Who is Lieutenant Haggerdin?",a="Lieutenant Haggerdin is a dwarf officer of the Stormpike Guard. He is stationed at the entrance to Alterac Valley on the Headland in the Alterac Mountains, where he oversees Alliance recruitment and awards battlefield honors.",al={"haggerdin","who is haggerdin","lieutenant haggerdin alterac"},it="identity"},{q="Where can I find Lieutenant Haggerdin?",a="You can find Lieutenant Haggerdin on the Headland in the northern Alterac Mountains, just outside the portal and gates leading into Alterac Valley.",al={"haggerdin location","where is lieutenant haggerdin","alterac valley entrance alliance"},it="place",gp=true},{q="What role does Haggerdin play in the Stormpike Guard?",a="Lieutenant Haggerdin is a field liaison and quartermaster officer for the Stormpike Guard. He administers recruitment trials such as the Proving Grounds and awards higher ranks and insignia as Alliance fighters earn standing with the Guard.",al={"what does haggerdin do","haggerdin quests","stormpike guard officer"},it="purpose"},{q="Why is the Alliance fighting in Alterac Valley?",a="The Stormpike Expedition entered Alterac Valley to excavate ancient relics and dwarven history. Their arrival sparked a fierce territorial conflict with the resident Frostwolf orcs and their Horde allies.",al={"why alterac valley","stormpike expedition goal","alterac conflict"},it="conflict"},{q="Can Horde players interact with Lieutenant Haggerdin?",a="No. Lieutenant Haggerdin is an active Alliance officer who attacks Horde champions approaching the Headland gate.",al={"is haggerdin hostile to horde","horde haggerdin","can horde talk to haggerdin"},it="hostile",gp=true},{q="What is the Proving Grounds trial?",a="The Proving Grounds is an introductory trial Lieutenant Haggerdin gives prospective Alliance soldiers. It tests their competence and resolve before they commit fully to the war effort in Alterac Valley.",al={"proving grounds quest","proving grounds alterac","haggerdin proving grounds"}},{q="Whose side is Lieutenant Haggerdin on?",a="Lieutenant Haggerdin is thoroughly loyal to the Alliance, serving specifically within the Stormpike Guard. Operating at the northern edge of the foothills near Alterac Valley, he acts as an officer and muster agent for Alliance forces rallying against the Frostwolf orcs.",al={"haggerdin faction","is haggerdin alliance","haggerdin allegiance"},it="side",add="1d45d886"},{q="What does Lieutenant Haggerdin want?",a="Haggerdin wants capable Alliance champions to bolster the Stormpike Guard's ranks in Alterac Valley. He tests new recruits to ensure they can survive the freezing wilderness, recognizes seasoned veterans with ranks and insignias as their deeds grow, and seeks the downfall of threats like the Winterax troll champion, Korrak.",al={"what does haggerdin want","haggerdin goals","haggerdin purpose"},it="wants",add="5fb68a23"},{q="Why is Lieutenant Haggerdin here in the Alterac foothills?",a="Lieutenant Haggerdin is stationed at the Headland overlooking the gate to Alterac Valley to organize and vet incoming Alliance forces. Because the ongoing clash between the Stormpike Expedition and the Frostwolf Clan demands constant reinforcement, he stands guard at the staging grounds to recruit and honor those willing to fight in the snow.",al={"why is haggerdin here","why is haggerdin in alterac","haggerdin post"},it="why_here",add="96f37aaa"},{q="Who is Lieutenant Haggerdin tied to?",a="Haggerdin is tied directly to the Stormpike Guard, the military arm of Ironforge's Stormpike Expedition led by General Vanndar Stormpike. He serves as an officer linking Alliance recruits arriving through the Alterac Mountains to the regiment fighting deep within Alterac Valley.",al={"haggerdin ties","haggerdin stormpike guard","who does haggerdin serve"},it="ties",add="9b7a183a"}},ang={["faction:Alliance"]="As an Alliance champion, you can find Lieutenant Haggerdin outside Alterac Valley. He offers credentials and official honors earned while fighting the Frostwolf Clan.",["race:Dwarf"]="As a dwarf, you may see Ironforge's determination in Lieutenant Haggerdin, a proud Stormpike officer seeking their titan heritage in Alterac's snowy crags.",["faction:Horde"]="As a Horde champion, you face Lieutenant Haggerdin at the Alliance portal into Alterac Valley. He directs reinforcements sent against the Frostwolf orcs."},kw={"alterac","dwarf","frostwolf","haggerdin","headland","ironforge","lieutenant","proving grounds","stormpike"},rel={"zone:alterac","topic:dwarf","topic:alliance","topic:horde","zone:hillsbrad","topic:alterac-kingdom"},src={"Lieutenant Haggerdin"}}
E["npc:lord-jorach-ravenholdt"] = {t="npc",n="Lord Jorach Ravenholdt",z="alterac",s="At Ravenholdt Manor, Lord Jorach Ravenholdt trains rogues and directs a war against the Syndicate. His estate lies in the Alterac Mountains.",h="At Ravenholdt Manor, Lord Jorach Ravenholdt trains rogues and directs a war against the Syndicate.",sec={{t="Master of the Assassin's League",b="Lord Jorach Ravenholdt commands the Assassin's League from a manor hidden among the crags between Alterac and Hillsbrad. A nobleman of mysterious heritage, he welcomes outlaws, cutpurses, and assassins of any allegiance, provided they show great skill and respect his authority. The league joins master thieves in espionage and killings for hire.\n\nRavenholdt despises the Syndicate, whose members are disgraced Alterac nobles turned outlaws. He sends his followers and visiting rogues to sabotage their camps and plunder their goods.",sp=0},{t="Secrets in the Shadows",b="Lord Jorach Ravenholdt directs operations across Azeroth while the fighting near his manor holds his attention. Rogues who prove loyal take on intricate work across continents to recover guarded artifacts. One effort sought a mysterious Sealed Azure Bag, stolen from Ravenholdt and carried to furbolgs in Azshara.\n\nTo recover it, Archmage Xylem had to decode its secrets, and an Azure Key had to be taken from the Sunken Temple. Ravenholdt also oversees the making of lethal compounds. He sends scouts across the realm to gather venom from ancient horrors.",sp=1}},faq={{q="Who is Lord Jorach Ravenholdt?",a="Lord Jorach Ravenholdt leads the Assassin's League, a covert society of rogues based at Ravenholdt Manor in the mountains above Hillsbrad Foothills. He trains master operatives in stealth and directs assassinations and intelligence gathering.",al={"who is jorach","ravenholdt leader","jorach lore"}},{q="Why does Ravenholdt hate the Syndicate?",a="Ravenholdt's estate lies in land contested by the Syndicate, a network of former Alterac nobles turned outlaws. He opposes their banditry and sends his assassins against their strongholds.",al={"why syndicate enemy","ravenholdt vs syndicate","syndicate rivalry"}},{q="Is Lord Ravenholdt affiliated with the Alliance or Horde?",a="Lord Jorach Ravenholdt's organization is independent. He welcomes rogues from both the Alliance and Horde at his manor, judging them by skill, discipline in stealth, and discretion rather than allegiance.",al={"is ravenholdt alliance","is jorach horde","ravenholdt faction"}},{q="What is inside the Sealed Azure Bag Jorach seeks?",a="What lies inside the Sealed Azure Bag remains a guarded secret. When Lord Jorach Ravenholdt receives the Azure Key and unlocks the enchanted satchel, eerie golden light washes over him. He stares inside in astonishment, then quickly puts it away.",al={"sealed azure bag contents","azure bag mystery","what did jorach get"},sp=1}},ang={["class:Rogue"]="As a rogue, you can seek Lord Jorach Ravenholdt's patronage. He offers training, poisons, and contracts to rogues who earn his trust."},kw={"alterac","assassin's league","azure key","jorach","ravenholdt","rogue","syndicate","xylem"},rel={"subzone:ravenholdt-manor","topic:ravenholdt","topic:syndicate","zone:alterac","npc:archmage-xylem","subzone:temple-of-atal-hakkar","quest:2300","npc:mathias-shaw"},src={"Lord Jorach Ravenholdt"}}
E["npc:warmaster-laggrond"] = {t="npc",n="Warmaster Laggrond",z="alterac",s="At Alterac Valley's entrance, Warmaster Laggrond prepares Horde fighters for the Frostwolf clan. From the valley entrance in the Alterac Mountains, he calls warriors to aid the Frostwolves.",h="At Alterac Valley's entrance, Warmaster Laggrond prepares Horde fighters for the Frostwolf clan.",sec={{t="Frontline Commander",b="Warmaster Laggrond directs the Horde's fight against the Stormpike Expedition at Alterac Valley's entrance. The cold is bitter there. He accepts only capable fighters to represent the Frostwolf clan and the wider Horde.",sp=0},{t="The Path of Honor",b="Warmaster Laggrond sends new combatants through the Proving Grounds before they enter battle. As warriors fight across the frozen peaks, he measures their standing. Those who earn renown among the Frostwolves receive his honor.",sp=0}},faq={{q="Where is Warmaster Laggrond located?",a="Warmaster Laggrond is near the Horde encampment at Alterac Valley's entrance portal, in the snowy passes of the Alterac Mountains north of Hillsbrad Foothills.",al={"laggrond location","where is laggrond","alterac valley entrance warmaster"},it="place",gp=true},{q="What is Warmaster Laggrond's role?",a="Warmaster Laggrond recruits fighters for the Horde's war in Alterac Valley. He tests new combatants and honors those who earn standing with the Frostwolf clan.",al={"what does laggrond do","laggrond purpose","why talk to laggrond"},it="purpose",gp=true},{q="What is the Proving Grounds quest?",a="Warmaster Laggrond asks prospective recruits to retrieve a Frostwolf banner from the Wildpaw Den in Alterac Valley. The trial tests their resourcefulness before they join the campaign.",al={"proving grounds horde","laggrond initial quest"},gp=true},{q="Why is the Horde fighting in Alterac Valley?",a="The Frostwolf clan claims Alterac Valley as its home after exile during the First War. The Stormpike Guard, an Alliance dwarven expedition, has pushed into the region in search of relics and territory. Their arrival sparked a bitter territorial war.",al={"why alterac valley","frostwolf war","alterac valley conflict"},it="conflict"},{q="Can Alliance players interact with Warmaster Laggrond?",a="No. Warmaster Laggrond is a devoted Horde champion. He attacks Alliance trespassers who approach his mountain outpost.",al={"can alliance talk to laggrond","laggrond hostile"},gp=true},{q="Who is Warmaster Laggrond?",a="Warmaster Laggrond is an orc officer stationed at the entrance to Alterac Valley in the snowy reaches of the Alterac Mountains. He serves the Frostwolf clan and the broader Horde war effort, evaluating arriving champions and directing capable soldiers toward the battle against the Stormpike dwarves.",al={"who is laggrond","warmaster laggrond lore","laggrond alterac"},it="identity",add="050e2655"},{q="Whose side is Warmaster Laggrond on?",a="Laggrond stands firmly with the Horde, specifically representing the interests of the Frostwolf clan. He regards the Alliance—especially the encroaching Stormpike Expedition—as invaders trespassing on ancestral Frostwolf territory.",al={"is laggrond horde","warmaster laggrond faction","laggrond alliance or horde"},it="side",add="ccc612bb"},{q="What does Warmaster Laggrond want?",a="Laggrond seeks stalwart champions willing to prove themselves in the harsh conflict of Alterac Valley. He wants the Frostwolf lands defended, the dwarven expedition crushed, and Horde fighters to earn standing and honor among the clan through blood and duty.",al={"what does laggrond want","laggrond goal","laggrond objective"},it="wants",add="29764588"},{q="Why is Warmaster Laggrond here?",a="Stationed right outside the portal to the valley, Laggrond acts as a gatekeeper and recruiter for the frontline. He inspects those who answer the Frostwolves' call to arms, ensuring only determined fighters carry the clan's banner into battle.",al={"why is laggrond in alterac","laggrond location purpose","why is warmaster laggrond here"},it="why_here",add="b3dc84d2"},{q="Who is Warmaster Laggrond tied to?",a="Laggrond answers to the leadership of the Frostwolf clan, fighting on behalf of General Drek'Thar and the Horde forces committed to holding Alterac Valley against dwarven excavation and conquest.",al={"laggrond ties","laggrond frostwolf","who does laggrond work for"},it="ties",add="6fc2678d"}},ang={["faction:Horde"]="Warmaster Laggrond is your first contact for the Alterac Valley war effort. He recognizes your battlefield achievements for the Frostwolf clan.",["race:Orc"]="As an orc, you answer Laggrond's summons to defend the Frostwolf clan's ancestral refuge from dwarven intrusion.",["class:Warrior"]="As a warrior, you face Laggrond's tests of frontline courage. They prove you can hold against heavy dwarven armor and vanguard charges."},kw={"alterac mountains","alterac valley","frostwolf","laggrond","proving grounds","pvp","stormpike","warmaster laggrond"},rel={"zone:alterac","topic:horde","zone:hillsbrad"},src={"Warmaster Laggrond"}}
E["npc:winstone-wolfe"] = {t="npc",n="Winstone Wolfe",z="alterac",s="At Ravenholdt Manor, Winstone Wolfe watches over the estate grounds. He serves Lord Jorach Ravenholdt's secretive organization, hidden between Hillsbrad and the Alterac Mountains.",h="At Ravenholdt Manor, Winstone Wolfe watches over the estate grounds.",sec={{t="A Fixer in the Mountains",b="Winstone Wolfe works with Lord Jorach Ravenholdt's syndicate at Ravenholdt Manor. Quiet and watchful, he handles business around the manor and keeps an eye on its grounds and groundskeepers. Only those with discretion and talent pass there undisturbed.",sp=0}},faq={{q="Who is Winstone Wolfe?",a="Winstone Wolfe is a human rogue working at Ravenholdt Manor, the League of Assassins' secluded headquarters high above Hillsbrad Foothills and the Alterac Mountains.",al={"who is wolfe","winstone wolfe lore","ravenholdt wolfe"},it="identity"},{q="Where can I find Winstone Wolfe?",a="Winstone Wolfe can be found at Ravenholdt Manor. A hidden path winds north through the mountains from the Durnholde Keep area in Hillsbrad Foothills.",al={"wolfe location","where is winstone wolfe","find winstone wolfe"},it="place",gp=true},{q="What is his role in Ravenholdt?",a="Winstone Wolfe works as an operative and guard around the manor. He watches the grounds and helps with the syndicate's logistical affairs.",al={"what does wolfe do","wolfe purpose"},it="purpose"},{q="Whose side is Winstone Wolfe on?",a="Winstone Wolfe is aligned with Ravenholdt, the secretive league of thieves and assassins operating out of Ravenholdt Manor. Tucked away in the hidden foothills overlooking Hillsbrad and Alterac, he serves the guild rather than either the Alliance or the Horde.",al={"winstone wolfe faction","who does winstone wolfe work for","is winstone wolfe ravenholdt"},it="side",add="2ccf77f3"},{q="Why is Winstone Wolfe here?",a="Wolfe operates out of Ravenholdt Manor as part of the hidden league of rogues based in the mountains. Whether watching the grounds or assisting fellow guild operatives, he remains where the guild's business is conducted.",al={"why is winstone wolfe at ravenholdt","winstone wolfe ravenholdt manor why"},it="why_here",add="d63e8a08"}},ang={["class:Rogue"]="As a rogue, you may recognize Winstone Wolfe as an operative at Ravenholdt Manor. Rogues travel into the mountains to hone their craft with the syndicate."},kw={"alterac","hillsbrad","ravenholdt","ravenholdt manor","rogue","winstone wolfe"},rel={"subzone:ravenholdt-manor","topic:ravenholdt","zone:hillsbrad","zone:alterac"},src={"Winstone Wolfe"}}
E["quest:1712"] = {t="quest",n="Cyclonian",z="alterac",s="At the summoning site, Cyclonian waits for a champion bold enough to face him. A special parchment names the rare materials needed to call forth the wind lord, whose whirlwind heart can strengthen a formidable weapon.",h="At the summoning site, Cyclonian waits for a champion bold enough to face him.",sec={{t="The Slumbering Wind Lord",b="A watcher has kept vigil at the summoning site for ages. The raging elemental wind lord awaits a combatant with the raw martial prowess to challenge and destroy him.",sp=0},{t="Summoning the Tempest",b="A special parchment names the rare materials needed to summon Cyclonian. Once the wind lord is called forth, you face him in direct combat. You may defeat him, or fall to his howling gale.",sp=0},{t="The Whirlwind Heart",b="Cyclonian's whirlwind heart is sought from the defeated elemental. Severed from him, its fierce elemental energies can be bound and infused into a weapon fit for an accomplished champion.",sp=1}},faq={{q="Who is Cyclonian?",a="Cyclonian is a powerful elemental wind lord and a grave threat. Observers have watched him for ages, waiting for a champion strong enough to challenge and defeat him.",al={"who is cyclonian","cyclonian lore","what is cyclonian"}},{q="Why must Cyclonian be summoned?",a="Cyclonian is summoned so a worthy champion can challenge and slay him. The victor can claim his whirlwind heart and have its power infused into a formidable weapon.",al={"why summon cyclonian","cyclonian purpose","why fight cyclonian"}},{q="What is the Whirlwind Heart?",a="The Whirlwind Heart is Cyclonian's core essence. Torn from the defeated wind lord, its tempestuous energies can be infused into a weapon of great martial power.",al={"what is whirlwind heart","heart of cyclonian","whirlwind heart purpose"}},{q="Who has been watching Cyclonian?",a="Bath'rah the Windwatcher in the Alterac Mountains has kept vigil over the site for ages. He searches endlessly for a true champion who can topple Cyclonian and master his tempestuous heart.",al={"who wants cyclonian dead","who watches cyclonian"}},{q="How is Cyclonian brought forth?",a="A special parchment records the rare reagents needed to summon Cyclonian and draw the wind lord into the world to be challenged.",al={"how to summon cyclonian","cyclonian ingredients"}},{q="What weapon is forged from Cyclonian?",a="The champion who gathers the necessary components, summons Cyclonian, and slays him earns a weapon infused with the latent fury of the elemental's whirlwind heart.",al={"cyclonian reward","what weapon from cyclonian"}}},ang={["class:Warrior"]="As a warrior, defeating Cyclonian tests your strength and martial mastery. Claim his whirlwind heart and use it to forge a potent weapon."},kw={"champion","cyclonian","elemental","summoning","whirlwind heart","wind lord"},m={cl={"WARRIOR"},id=1712},src={"In-game quest text: Cyclonian"},fv=true}
E["quest:1713"] = {t="quest",n="The Summoning",z="alterac",s="At Bath'rah Windwatcher's camp, a warrior faces a trial against Cyclonian, the wind lord. Slay the elemental and claim the Whirlwind Heart, whose storm force can be bound into a weapon.",h="At Bath'rah Windwatcher's camp, a warrior faces a trial against Cyclonian, the wind lord.",sec={{t="Calling the Tempest",b="Bath'rah Windwatcher has prepared an ancient ritual to summon Cyclonian into the mortal realm. The fearsome elemental is known as the wind lord. There will be no bargain with the tempest. An able champion must strike it down as soon as it takes form.",sp=0},{t="The Heart of the Storm",b="Cyclonian's Whirlwind Heart sustains his physical form. When the wind lord falls, Bath'rah wrenches the heart free and harnesses the gale within. Its volatile power can imbue a weapon with the force of the storm.",sp=0}},faq={{q="Who is Cyclonian?",a="Cyclonian is a powerful elemental known as the wind lord. Bath'rah Windwatcher's ritual calls him forth as a fierce tempest, and he must be defeated to claim the essence sealed in his core.",al={"who is cyclonian","what is cyclonian","cyclonian lore"}},{q="What is the Whirlwind Heart?",a="The Whirlwind Heart is Cyclonian's elemental core. Bath'rah Windwatcher needs it to bind the wind lord's swirling, destructive power into a weapon.",al={"what is whirlwind heart","why need whirlwind heart","whirlwind heart use"}},{q="Who is Bath'rah Windwatcher?",a="Bath'rah Windwatcher is a troll mystic who lives in the wilderness and knows how to summon Cyclonian. He guides warriors through the ritual, then uses the fallen elemental's heart to forge mighty weapons.",al={"who is bathrah","bathrah windwatcher","quest giver the summoning"}},{q="Why is Cyclonian being summoned?",a="Cyclonian is summoned so a warrior can face and slay the wind lord, then claim his elemental heart. Its power can be bound into a weapon.",al={"why summon cyclonian","purpose of the summoning","reason to summon"}},{q="What happens after Cyclonian is defeated?",a="After Cyclonian falls, Bath'rah can harness the elemental power in his Whirlwind Heart to empower a weapon with Cyclonian's stormcraft.",al={"what happens after defeating cyclonian","cyclonian reward lore","after the summoning"}},{q="Where does the summoning take place?",a="The ritual takes place at Bath'rah Windwatcher's camp. There, the mystic gathers the primal focus needed to draw Cyclonian from the elemental realm into the physical world.",al={"where does the ritual happen","the summoning location"}}},ang={["class:Warrior"]="As a warrior, facing Cyclonian and claiming the Whirlwind Heart is a proving ground. It yields a weapon infused with the raw power of the tempest.",["race:Troll"]="As a troll, you know Bath'rah Windwatcher's primal arts reach far beyond civilization. His command of wind elementals reflects the deep mystical traditions of troll shamans and witch doctors."},kw={"bath'rah windwatcher","bathrah","cyclonian","elemental","the summoning","warrior quest","whirlwind heart","wind lord"},rel={"quest:1712"},m={cl={"WARRIOR"},id=1713},src={"In-game quest text: The Summoning"},fv=true}
E["quest:1714"] = {t="quest",n="Essence of the Exile",z="alterac",s="At the cauldron, Essence of the Exile draws travelers with its beckoning vapors. Charms set off a violent reaction that reveals molten rock.",h="At the cauldron, Essence of the Exile draws travelers with its beckoning vapors.",sec={{t="A Beckoning Cauldron",b="A bubbling cauldron sends out vapors that draw travelers to its churning depths. Specific enchanted charms stir an intense reaction within the vessel.",sp=0},{t="The Molten Crucible",b="The charms sink slowly through the liquid. Then a large bubble rises and bursts, revealing a churning lump of molten rock forged from the combined materials.",sp=0}},faq={{q="What is the Essence of the Exile?",a="Essence of the Exile is a transmutation ritual performed at a bubbling cauldron. Charms set off a violent reaction that yields a churning lump of molten rock.",al={"what is essence of the exile","essence of the exile quest"}},{q="What happens when charms are placed in the cauldron?",a="The cauldron's vapors draw travelers close. Charms sink to the bottom, then a large bubble bursts at the surface and leaves molten stone behind.",al={"what happens at the cauldron","how does the cauldron work"}},{q="What does the cauldron produce?",a="When a large bubble bursts at the surface, a churning lump of molten rock is revealed inside the cauldron.",al={"what is produced from the cauldron","what do you get from essence of the exile"}},{q="Where is the cauldron used for this ritual?",a="The ritual takes place at a boiling cauldron whose hot vapors beckon travelers. There, the vessel transforms its contents.",al={"cauldron location","where do i find the cauldron"}},{q="Why are charms placed into the cauldron?",a="The charms are consumed as reagents in the cauldron's depths. Their presence in the heated liquid helps form the molten rock.",al={"what are the charms for","why do charms go in the cauldron"}},{q="Why is the cauldron constantly bubbling?",a="The bubbling liquid and beckoning vapors mark an active reaction within the vessel. It is ready to transform whatever enters its depths.",al={"why is it bubbling","what are the vapors"}}},ang={["class:Mage"]="Alchemical cauldrons and elemental transmutations can bind separate essences into solid form through volatile magic.",["class:Shaman"]="Even when bubbling cauldrons churn molten rock, working with elemental essences calls for understanding the primal forces at play."},kw={"bubble","cauldron","charms","essence of the exile","molten rock","transmutation","vapors"},rel={"quest:1712"},m={cl={"WARRIOR"},id=1714},src={"In-game quest text: Essence of the Exile"},fv=true}
E["quest:1792"] = {t="quest",n="Whirlwind Weapon",z="alterac",s="A warrior's chosen weapon awaits the storm Cyclonian left behind. The whirlwind heart can bind the elemental's fury into a forged vessel.",h="A warrior's chosen weapon awaits the storm Cyclonian left behind.",sec={{t="Infusing the Storm",b="After Cyclonian falls and the warrior claims its heart, a craftsperson prepares a weapon to hold the storm's power. The heart is fused into the chosen arm, turning forged metal into a channel for elemental fury.",sp=0},{t="The Power of Cyclonian",b="Cyclonian's heart holds the violence of howling winds and tempestuous gales. Bound into a forged weapon, it lends the wielder the living might of the storm alongside their own martial skill. Each strike carries the force of the defeated elemental, whose storm now rages in the hands of its vanquisher.",sp=0}},faq={{q="What is the Whirlwind Weapon quest?",a="A warrior can bind Cyclonian's whirlwind heart into a chosen weapon, joining the elemental's power with the warrior's own strength.",al={"what is whirlwind weapon","whirlwind weapon lore","what is this quest"}},{q="Who is Cyclonian?",a="Cyclonian is an elemental manifestation of wind and storm. Its defeat yields the whirlwind heart, which can bind primal wind energy into a physical weapon.",al={"who is cyclonian","cyclonian lore","what is cyclonian"}},{q="What is the whirlwind heart?",a="The whirlwind heart is Cyclonian's core, claimed when the elemental is defeated. It holds the tempest's fury and can be bound into a forged vessel chosen by the warrior.",al={"what is whirlwind heart","cyclonian heart","heart of cyclonian"}},{q="How is the weapon empowered?",a="The warrior chooses a forged weapon and has Cyclonian's whirlwind heart bound into it. The elemental's fury then courses through the steel.",al={"how is whirlwind weapon made","vessel of choice","forging whirlwind weapon"}},{q="What choices are offered for the weapon?",a="A warrior chooses the weapon that will receive Cyclonian's storm essence.",al={"which weapon can i pick","whirlwind choices","what weapons are offered"}},{q="Why is Cyclonian's power sought after?",a="Warriors seek Cyclonian's power to command the fury of a living gale through their weapons.",al={"why does warrior want whirlwind weapon","whirlwind weapon importance"}}},ang={["class:Warrior"]="As a warrior, you can claim a weapon infused with the tempestuous force of Cyclonian."},kw={"cyclonian","elemental","storm","vessel","warrior weapon","whirlwind heart","whirlwind weapon"},rel={"quest:1712"},m={cl={"WARRIOR"},id=1792},src={"In-game quest text: Whirlwind Weapon"},fv=true}
E["quest:506"] = {t="quest",n="Blackmoore's Legacy",z="alterac",s="Gol'dir is already free and carries word to Krusk in Tarren Mill. Aliden Perenolde, leader of the Syndicate, visited him and spoke of enslaving orcs who resist. Perenolde brought Elysa, who wears the pendant the Warchief desires.",h="Gol'dir is already free and carries word to Krusk in Tarren Mill.",sec={{t="A Visit to the Prisoner",b="Gol'dir has word for Krusk after a visit from Aliden Perenolde, leader of the Syndicate. Perenolde called himself lord of the land and spoke of enslaving orcs who resist him. His father and mentor, the despised Blackmoore, had planned the same.\n\nGol'dir sends you to carry this news to Krusk in Tarren Mill. He will follow once he has settled his own business where he is.",sp=0},{t="Elysa's Pendant",b="Perenolde also brought his mistress, a slight girl named Elysa. Around her neck hung the pendant the Warchief desires.",sp=0},{t="Krusk's Answer",b="Krusk answers Perenolde's threat with anger. He vows the orcs will never submit and sets resistance alongside the effort to recover the trinket the Warchief desires. Krusk says achieving either goal will bring the other within reach.",sp=1}},faq={{q="Who gives this quest?",a="Gol'dir gives this to you after you free him from the Syndicate.",al={"who gives blackmoore's legacy","quest giver","goldir"}},{q="Who should receive the news?",a="Bring the news to Krusk in Tarren Mill.",al={"where do i go","who to talk to","turn in location"}},{q="What did Aliden Perenolde reveal to Gol'dir?",a="Aliden Perenolde, leader of the Syndicate, told Gol'dir he meant to enslave orcs who resisted him. His father and mentor, the despised Blackmoore, had planned the same.",al={"perenolde plan","syndicate plans","what did perenolde say"}},{q="What else did Gol'dir notice during the visit?",a="Perenolde brought his mistress, a girl named Elysa, who wore the pendant the Warchief desires around her neck.",al={"elysa necklace","warchief pendant","mistress"}},{q="What came before this quest?",a="You freed Gol'dir from the Syndicate.",al={"previous quest","what came before"}}},kw={"aliden","blackmoore","elysa","goldir","krusk","legacy","pendant","perenolde","syndicate","tarren mill"},rel={"npc:krusk","quest:503","quest:507","subzone:tarren-mill","topic:syndicate"},m={start="Gol'dir",["end"]="Krusk",level="36",faction="Horde",id=506},src={"Blackmoore's Legacy"}}
E["quest:508"] = {t="quest",n="Taretha's Gift",z="alterac",s="Elysa gives up Taretha's Gift and asks for peace. After the step with Lord Aliden Perenolde, you carry the pendant to Krusk in Tarren Mill.",h="Elysa gives up Taretha's Gift and asks for peace.",sec={{t="The Pendant",b="Elysa wants no memory of Lord Aliden Perenolde. She gives you the pendant and asks only to be left in peace. It once belonged to Taretha Foxton, Thrall's childhood friend. You carry it to Krusk in Tarren Mill, returning it to the orcs.",sp=0},{t="Krusk's Verdict",b="Krusk finds it strange that the Warchief would go to such lengths for a trinket. He does not claim to understand Thrall, but follows his orders all the same. Krusk praises your work and expects Thrall will be pleased to hear of it.",sp=1}},faq={{q="Who hands over Taretha's necklace?",a="Elysa gives up the necklace without argument. She wants no memory of Lord Aliden Perenolde and asks only to be left in peace.",al={"who gives the pendant","where do you get taretha's necklace","who starts taretha's gift"}},{q="To whom must the necklace be returned?",a="Bring it to Krusk, who waits at Tarren Mill.",al={"who turns in taretha's gift","where do i bring the pendant","krusk location"}},{q="Whose pendant was it?",a="The pendant belonged to Taretha Foxton, Thrall's childhood friend. Returning it gives the orcs a keepsake of hers.",al={"why does thrall want the pendant","taretha foxton necklace significance","what is taretha's gift"}},{q="What comes before this in the chain?",a="The step involving Lord Aliden Perenolde comes before this. This is the last part of the chain.",al={"previous quest","prerequisite for taretha's gift"}}},kw={"aliden perenolde","elysa","hillsbrad foothills","krusk","taretha's gift","taretha's necklace","tarren mill","thrall"},rel={"quest:507","npc:krusk","npc:thrall","subzone:tarren-mill","zone:hillsbrad","zone:alterac","topic:horde"},m={start="Elysa",["end"]="Krusk",level="40",faction="Horde",id=508},src={"Taretha's Gift"}}
E["quest:510"] = {t="quest",n="Foreboding Plans",z="alterac",s="The Syndicate's papers call for supplies to reach Southshore soon, where Magistrate Henry Maleb awaits them.",h="The Syndicate's papers call for supplies to reach Southshore soon, where Magistrate Henry Maleb awaits them.",sec={{t="The Supply List",b="The Syndicate papers list food, weapons and clothing. They also call for masks, oil and poison. The supplies are needed soon for an important undertaking against Southshore. Magistrate Henry Maleb is to receive them there.",sp=0},{t="Maleb's Verdict",b="Magistrate Henry Maleb finds the documents troubling. Their words and the Syndicate's past deeds lead him to a grim judgment: the cutthroats have gone to war against the town.",sp=1}},faq={{q="What do the Syndicate documents say?",a="The documents list food, weapons and clothing, along with masks, oil and poison. They say the supplies are needed soon for an important undertaking against Southshore.",al={"what are the foreboding plans","syndicate documents contents","what is in the plans"}},{q="Who should see these plans?",a="Magistrate Henry Maleb in Southshore.",al={"who do i bring the plans to","foreboding plans turn in","where do the plans go"}}},kw={"alterac mountains","foreboding plans","magistrate henry maleb","southshore","syndicate","syndicate documents"},rel={"quest:512","npc:magistrate-henry-maleb","subzone:southshore","topic:syndicate","zone:alterac"},m={start="Syndicate Documents",["end"]="Magistrate Henry Maleb",level="34",faction="Alliance",id=510},src={"Foreboding Plans (quest)"}}
E["quest:511"] = {t="quest",n="Encrypted Letter",z="alterac",s="Among the Syndicate papers, one letter cannot be read. You take it to Loremaster Dibbs in Southshore.",h="Among the Syndicate papers, one letter cannot be read.",sec={{t="A Letter No One Can Read",b="Among the Syndicate documents, one letter is written in a cipher no one can read. You bring it to Loremaster Dibbs in Southshore.",sp=0},{t="What Dibbs Makes of It",b="Loremaster Dibbs has never seen this kind of cipher before. He still has much to learn before he can understand it.",sp=1}},faq={{q="Where does the letter come from?",a="The letter is one of several on a table among the Syndicate documents, and its meaning is unreadable.",al={"letter origin","where find letter","encrypted letter start"}},{q="Who is the letter taken to?",a="You take the letter to Loremaster Dibbs in Southshore.",al={"who reads letter","who can decipher it","dibbs letter"}}},kw={"alterac","encrypted letter","hillsbrad foothills","loremaster dibbs","southshore","syndicate documents"},rel={"quest:514","subzone:southshore","zone:hillsbrad","zone:alterac"},m={start="Syndicate Documents",["end"]="Loremaster Dibbs",level="34",faction="Alliance",id=511},src={"Encrypted Letter (Hillsbrad Foothills)"}}
E["quest:522"] = {t="quest",n="Assassin's Contract",z="alterac",s="In Hillsbrad Foothills, a Shadowy Assassin bears a contract naming Magistrate Henry Maleb for death. You are to carry it to Maleb in Southshore, where red wax bears a distinctive signet ring's mark.",h="In Hillsbrad Foothills, a Shadowy Assassin bears a contract naming Magistrate Henry Maleb for death.",sec={{t="A Marked Magistrate",b="A Shadowy Assassin carries a contract in Hillsbrad Foothills. It names Magistrate Henry Maleb for death, and a distinctive signet ring has marked the red wax. Bring the paper to Maleb in Southshore.",sp=0},{t="Maleb's Verdict",b="Magistrate Henry Maleb reads the contract and says it explains Southshore's recent attack. He is certain the Syndicate wants his life, as it wanted the previous magistrate's.",sp=1}},faq={{q="What is written in the contract?",a="The contract orders Magistrate Henry Maleb's killing. Red wax seals it, marked by a distinctive signet ring.",al={"what does the contract say","assassins contract details","who is the target"}},{q="Where does this contract originate?",a="A Shadowy Assassin carries the contract in Hillsbrad Foothills.",al={"who dropped the contract","where to find contract","shadowy assassin drop"}},{q="To whom should the contract be delivered?",a="Bring the contract to Magistrate Henry Maleb in Southshore. He is the magistrate it names for death.",al={"who do I give the contract to","where to turn in assassins contract","maleb location"}}},kw={"assassin's contract","hillsbrad foothills","magistrate henry maleb","shadowy assassin","signet ring","southshore","syndicate"},rel={"npc:magistrate-henry-maleb","quest:523","subzone:southshore","zone:hillsbrad","topic:syndicate","zone:alterac"},m={start="Assassin's Contract",["end"]="Magistrate Henry Maleb",level="38",faction="Alliance",id=522},src={"Assassin's Contract (quest)"}}
E["quest:535"] = {t="quest",n="Valik",z="alterac",s="In a Syndicate camp, Valik lies dying with an enemy before them. Valik expects you to kill them, but offers answers for a mug of Southshore Stout.",h="In a Syndicate camp, Valik lies dying with an enemy before them.",sec={{t="A Dying Bargain",b="Henchman Valik lies wounded in the Syndicate camp, with you standing before them as an enemy. They expect you to kill them all the same. Yet Valik offers answers to your questions if you bring a mug of Southshore Stout to the camp. They even wonder aloud whether your kind drinks at all.",sp=0},{t="Valik's Last Drink",b="Valik calls the stout the sweetest thing they have ever tasted, though death waits. They hand you something of no use to the dead. Then Valik tells you to get on with it.",sp=1}},faq={{q="Who is Valik?",a="Henchman Valik lies injured and dying in the Syndicate camp.",al={"henchman valik","who is valik","valik alterac"}},{q="What does Valik want?",a="Valik wants you to bring a mug of Southshore Stout to the Syndicate camp.",al={"what does valik need","valik drink","valik stout"}},{q="What does Valik promise in return for the stout?",a="Valik promises to share what you seek, though they expect you to kill them afterward.",al={"valik reward lore","what does valik tell you","valik trade"}}},kw={"alterac mountains","henchman valik","southshore stout","syndicate","valik"},rel={"subzone:southshore","topic:syndicate","zone:alterac"},m={start="Henchman Valik",["end"]="Henchman Valik",level="34",faction="Horde",id=535},src={"Valik (quest)"}}
E["quest:551"] = {t="quest",n="The Ensorcelled Parchment",z="alterac",s="At the top of The Ensorcelled Parchment, Nagaz is the only name clear. A spell hides the rest, so you take it to Loremaster Dibbs in Southshore.",h="At the top of The Ensorcelled Parchment, Nagaz is the only name clear.",sec={{t="A Spell-Veiled Parchment",b="A spell keeps the parchment's writing from being read. Only Nagaz can be made out at the top. You take it to Loremaster Dibbs in Southshore.",sp=0},{t="What Dibbs Makes of It",b="Dibbs asks if the parchment holds more encrypted notes. He wishes he could decipher every odd scrap of writing that drifts out of Alterac. But he admits he lacks the knowledge.",sp=1}},faq={{q="What is written on the parchment?",a="A spell hides the writing, except for one word at the top: Nagaz.",al={"what does the ensorcelled parchment say","parchment text","ensorcelled parchment words"}},{q="Who should see the parchment?",a="Show the parchment to Loremaster Dibbs in Southshore. He takes in scraps of lore gathered from the mountains.",al={"loremaster dibbs","who is dibbs","southshore loremaster"}}},kw={"alterac","dibbs","ensorcelled","nagaz","parchment","southshore"},rel={"quest:554","subzone:southshore","zone:alterac","topic:alterac-kingdom"},m={start="Ensorcelled Parchment",["end"]="Loremaster Dibbs",level="40",faction="Alliance",id=551},src={"The Ensorcelled Parchment"}}
E["quest:603"] = {t="quest",n="Ansirem's Key",z="alterac",s="An ancient troll dagger may weaken the magic empowering the Stone of the Tides. Archmage Ansirem Runeweaver found the blade in Stranglethorn, then gave it to his daughter Catelyn, who left home for the pirates of Booty Bay.",h="An ancient troll dagger may weaken the magic empowering the Stone of the Tides.",sec={{t="A Wayward Daughter",b="Archmage Ansirem Runeweaver has found that an altar, or focal point, amplifies the Stone of the Tides. To overpower that magic, he needs an ancient troll dagger he uncovered while researching in Stranglethorn. He gave the blade to his daughter Catelyn long ago. Headstrong, she left home for the pirates of Booty Bay.",sp=0},{t="A Fighter Disarmed",b="In Booty Bay, Catelyn no longer wears the dagger at her hip. Once the settlement's sharpest knife fighter, she lost a duel to one of the Bloodsail Buccaneers. Her victor took the troll blade as a trophy. Now disarmed and humiliated, Catelyn faces bitter mockery from her fellow cutthroats.",sp=1}},faq={{q="Why does Archmage Ansirem need the troll dagger?",a="The mage holding the Stone of the Tides channels its magic through an altar. Ansirem hopes an ancient troll dagger can disrupt that empowerment by overpowering it.",al={"why need dagger","ansirem key purpose","what is the dagger for"}},{q="Who is Catelyn?",a="Catelyn is the headstrong daughter of Archmage Ansirem Runeweaver. She left her father to take up life as a pirate in Booty Bay.",al={"who is catelyn","ansirem daughter","catelyn the blade"}},{q="Where did Ansirem find the dagger originally?",a="Ansirem found the relic while researching in the jungles of Stranglethorn Vale, then gave it to his daughter.",al={"dagger origin","where did ansirem find dagger"}},{q="Where can Catelyn be found?",a="Catelyn lives in Booty Bay, the pirate haven at the southern tip of Stranglethorn Vale.",al={"where is catelyn","catelyn location"}}},kw={"ansirem","booty bay","catelyn","dagger","runeweaver","stone of the tides","troll relic"},rel={"npc:archmage-ansirem-runeweaver","quest:602","quest:578","subzone:booty-bay","zone:stranglethorn","topic:pirate","topic:troll"},m={start="Archmage Ansirem Runeweaver",["end"]="Catelyn the Blade",level="37",faction="Alliance",id=603},src={"Ansirem's Key"}}
E["quest:7082"] = {t="quest",n="The Graveyards of Alterac",z="alterac",s="Corporal Teeka Bloodsnarl asks you to assault an Alliance graveyard in Alterac Valley, then return to her in the Alterac Mountains.",h="Corporal Teeka Bloodsnarl asks you to assault an Alliance graveyard in Alterac Valley, then return to her in...",sec={{t="A Graveyard Assault",b="In the Alterac Mountains, Corporal Teeka Bloodsnarl sends you to assault a graveyard. Then you are to return to her.",sp=0}},faq={{q="Who asks me to assault a graveyard?",a="Corporal Teeka Bloodsnarl, in the Alterac Mountains, asks you to assault a graveyard in Alterac Valley.",al={"who gave this","Teeka graveyard","graveyard task"}},{q="Where is the graveyard?",a="The graveyards are in Alterac Valley. Pick one held by the Alliance, marked by an Alliance banner.",al={"graveyard location","where to go","Alterac graveyard"}},{q="What does Teeka ask me to do?",a="Teeka asks you to assault a graveyard, then return to her in the Alterac Mountains.",al={"what do I do","graveyard request","what's the task"}}},kw={"alterac","alterac mountains","corporal teeka bloodsnarl","graveyard assault","graveyards"},rel={"zone:alterac"},m={faction="Horde",id=7082},src={"In-game quest text: The Graveyards of Alterac"},fv=true}
E["quest:7142"] = {t="quest",n="The Battle for Alterac",z="alterac",s="Voggah Deathgrip sends you into Alterac Valley to defeat the dwarven general Vanndar Stormpike. His defeat is the purpose of this undertaking.",h="Voggah Deathgrip sends you into Alterac Valley to defeat the dwarven general Vanndar Stormpike.",sec={{t="A General in Alterac",b="In the Alterac Mountains, Voggah Deathgrip sends you toward Alterac Valley. The dwarven general Vanndar Stormpike is your target, and Voggah awaits your return.",sp=0}},faq={{q="Who sends me to Alterac Valley?",a="Voggah Deathgrip sends you into Alterac Valley to defeat Vanndar Stormpike.",al={"who is Voggah","voggah task"}},{q="Who is the target?",a="The target is Vanndar Stormpike, a dwarven general.",al={"alterac general","who is Vanndar"}},{q="Where do I go?",a="You are sent into Alterac Valley.",al={"where is the battle","alterac valley"}},{q="Who am I meant to return to?",a="After defeating Vanndar Stormpike, you are to return to Voggah Deathgrip in the Alterac Mountains.",al={"return to who","Voggah"}}},kw={"alterac","alterac mountains","alterac valley","dwarven general","vanndar stormpike","voggah deathgrip"},rel={"zone:alteracvalley","npc:vanndar-stormpike","zone:alterac"},m={faction="Horde",id=7142},src={"In-game quest text: The Battle for Alterac"},fv=true}
E["quest:7162"] = {t="quest",n="Proving Grounds",z="alterac",s="In Alterac, recruits face a trial before they may join the Stormpike Guard. Lieutenant Haggerdin sends them into Icewing Caverns for a planted battle standard. Success earns an official Stormpike Insignia and opens the way through the expedition’s ranks.",h="In Alterac, recruits face a trial before they may join the Stormpike Guard.",sec={{t="A Measure of Courage",b="The Stormpike Guard fights the Frostwolf Clan in Alterac Valley. Lieutenant Haggerdin directs Alliance forces from their encampment in the Alterac Mountains. Before recruits reach the battlefield, he tests their skill and nerve in Icewing Caverns southwest of Dun Baldar.",sp=0},{t="The Icewing Caverns",b="Deep in Icewing Caverns, a Stormpike banner waits among the frozen tunnels. Frost harpies nest in the icy recesses and attack unwary trespassers. A recruit who brings the banner back intact has crossed dangerous ground, faced its predators, and kept discipline under pressure.",sp=0},{t="The Stormpike Insignia",b="Return from the caverns with the standard, and you earn a Stormpike initiate’s insignia and a place in the expeditionary force. Haggerdin says the insignia can improve as you earn greater honor on the battlefield. The Eye of Command is one distant aim.",sp=0}},faq={{q="Who is Lieutenant Haggerdin?",a="Lieutenant Haggerdin is an Alliance officer in the Alterac Mountains who oversees Stormpike Guard recruitment and field recognition. He tests prospective fighters and rewards their service with military insignias.",al={"lieutenant haggerdin","haggerdin","who gives proving grounds"},it="identity"},{q="Where are the Icewing Caverns?",a="Icewing Caverns lie southwest of Dun Baldar, the Alliance stronghold in Alterac Valley. Their winding tunnels run beneath ice and stone.",al={"icewing caverns location","where is icewing caverns","banner location"},it="place",gp=true},{q="What threats dwell inside the Icewing Caverns?",a="Ferocious ice harpies live in Icewing Caverns. Haggerdin warns that they ambush trespassers and tear out their throats.",al={"harpies","what is in icewing caverns","icewing harpies"},it="danger"},{q="Why does the Stormpike Guard require this test?",a="The Stormpike Guard fights a brutal war against the Frostwolf orcs. Haggerdin tests recruits before they join the main lines, so each soldier bearing the banner can fight in harsh conditions.",al={"why proving grounds","why do the banner trial","stormpike initiation"},it="motive"},{q="What is the reward for completing the proving ground?",a="Return with the standard, and you earn a Stormpike initiate’s insignia. Haggerdin can improve it as you gain honor in Alterac Valley.",al={"stormpike insignia","eye of command","proving grounds reward"},gp=true},{q="Who are the Frostwolves mentioned by Haggerdin?",a="The Frostwolf Clan is an orcish clan that has lived in Alterac Valley since its exile decades ago. The Stormpike Guard sees them as hostile savages who obstruct Alliance interests and excavation in the valley.",al={"frostwolf savages","who are the frostwolves","frostwolf clan"},it="threat"},{q="What is the purpose of the Stormpike Banner in the caverns?",a="Planted deep inside the dangerous Icewing Caverns, the Stormpike Banner serves as a trial marker for recruits seeking to enlist in the expeditionary force. To claim it, you must brave the vicious harpies that infest the caves, demonstrating the courage, resourcefulness, and grit required of a true Stormpike soldier before ever setting foot on the open battlefield.",al={"what is stormpike banner","why banner in icewing caverns","stormpike banner purpose"},it="item",add="b9e84d22"}},ang={["faction:Alliance"]="The Stormpike expedition is the Alliance’s main military effort in Alterac. It joins dwarven archaeological ambitions with the defense of Alliance territory against the Horde.",["race:Dwarf"]="As a dwarf, you join a guard led mostly by Ironforge dwarves who seek ancestral relics and titan mysteries. This trial can be your first step into one of your race’s proudest military units."},kw={"dun baldar","haggerdin","harpies","icewing caverns","insignia","proving grounds","stormpike","stormpike banner"},rel={"npc:lieutenant-haggerdin","zone:alterac","zone:hillsbrad","topic:alterac-kingdom"},m={start="Lieutenant Haggerdin",faction="Alliance",id=7162,ri={"Stormpike Banner"}},src={"Proving Grounds (Alterac Valley) (Alliance)"}}
E["quest:79365"] = {t="quest",n="With Wind Beneath Your Wings",z="alterac",s="A Squall-breakers Potion offers brief protection from the storm’s elements. You are sent back to Rau Cliffrunner at Freewind Post in Thousand Needles.",h="A Squall-breakers Potion offers brief protection from the storm’s elements.",sec={{t="Back to Freewind",b="A storm still threatens your friends, and the potion’s protection lasts only a short while. Return to Rau Cliffrunner at Freewind Post in Thousand Needles, where your friends are waiting in need.",sp=0}},faq={{q="What does the potion do?",a="The Squall-breakers Potion protects you against the elements of the storm for a short while.",al={"potion protection","squall-breakers potion"}},{q="Who should I return to?",a="Return to Rau Cliffrunner at Freewind Post in Thousand Needles.",al={"where to go","rau cliffrunner"}},{q="Why am I going back?",a="You are being sent back to your friends in need.",al={"friends in need","return to friends"}}},kw={"freewind post","rau cliffrunner","squall-breakers potion","storm","thousand needles"},rel={"npc:rau-cliffrunner","subzone:freewind-post","zone:thousandneedles"},m={id=79365},src={"In-game quest text: With Wind Beneath Your Wings"},fv=true}
E["quest:79442"] = {t="quest",n="The Tempest's Weapons",z="alterac",s="An old shaman in the Alterac Mountains may know how to use the Eye of the Tempest. You bring him the artifact so he can craft with its storm magic.",h="An old shaman in the Alterac Mountains may know how to use the Eye of the Tempest.",sec={{t="An Old Shaman",b="After the battle with the elementals, you bring the Eye of the Tempest to Bath'rah the Windwatcher in the Alterac Mountains. He has an eye for storm elemental magic and sees power in the artifact. Bath'rah says he has not worked with anything like it in a long time, and urges you to take good care of it.",sp=0}},faq={{q="Who is Bath'rah?",a="Bath'rah the Windwatcher is an old shaman in the Alterac Mountains with an eye for storm elemental magic.",al={"Bath'rah Windwatcher","old shaman","who is bathrah"}},{q="What is the Eye of the Tempest?",a="The Eye of the Tempest is a powerful artifact associated with storm elemental magic.",al={"tempest eye","eye artifact","what's the eye"}},{q="Why bring the Eye to Bath'rah?",a="Bath'rah may be able to craft something with the Eye of the Tempest because he understands storm elemental magic.",al={"why bathrah","tempest weapons quest","bring eye where"}},{q="What does Bath'rah say about the artifact?",a="Bath'rah calls the Eye of the Tempest powerful and says he has not crafted with anything like it in a long time.",al={"bathrah reaction","what does he say","eye completion"}}},ang={["class:Shaman"]="As a shaman, you bring a powerful artifact of storm elemental magic to Bath'rah, an old shaman with an eye for that magic."},kw={"alterac mountains","bath'rah","bath'rah the windwatcher","eye of the tempest","shaman","storm elemental magic","the tempest's weapons"},rel={"quest:1791","npc:bath-rah-the-windwatcher","zone:alterac","topic:shaman"},m={id=79442},src={"In-game quest text: The Tempest's Weapons"},fv=true}
E["quest:8234"] = {t="quest",n="Sealed Azure Bag",z="alterac",s="In Azshara, you are asked to retrieve a sealed bag from a Timbermaw Shaman and take it to Archmage Xylem. The request links the shaman and the mage through the bag.",h="In Azshara, you are asked to retrieve a sealed bag from a Timbermaw Shaman and take it to Archmage Xylem.",sec={{t="A Sealed Bag",b="A Timbermaw Shaman in Azshara has the Sealed Azure Bag, and Archmage Xylem is waiting for it in the same land. You are asked to carry the bag from one to the other.",sp=0}},faq={{q="Who has the Sealed Azure Bag?",a="A Timbermaw Shaman in Azshara has the Sealed Azure Bag.",al={"who has the bag","timbermaw bag"}},{q="Who wants the bag?",a="Archmage Xylem in Azshara is to receive the Sealed Azure Bag.",al={"who gets the bag","where take bag"}},{q="Where do I find the bag?",a="The Sealed Azure Bag is with a Timbermaw Shaman in Azshara.",al={"bag location","where is sealed azure bag"}},{q="Where is Archmage Xylem?",a="Archmage Xylem is in Azshara.",al={"xylem location","where is xylem"}}},kw={"archmage xylem","azshara","bag","sealed azure bag","timbermaw shaman"},rel={"zone:azshara","npc:archmage-xylem","topic:shaman"},m={cl={"ROGUE"},id=8234},src={"In-game quest text: Sealed Azure Bag"},fv=true}
E["quest:8249"] = {t="quest",n="Junkboxes Needed",z="alterac",s="Fahrad keeps Ravenholdt supplied with locked boxes for rogue training. He trades specialized throwing knives for authentic heavy junkboxes, and his demand never ends.",h="Fahrad keeps Ravenholdt supplied with locked boxes for rogue training.",sec={{t="Sharpening Ravenholdt's Talons",b="Ravenholdt Manor hides in the mountains above Hillsbrad Foothills, where training never ceases. Master thief Fahrad oversees the guild's operatives and prizes skill at picking locks. Zan supplies practice contraptions for new recruits. Fahrad finds them too crude for experienced thieves who must open stubborn mechanisms in the field.",sp=0},{t="A Curiously Open Arrangement",b="Fahrad pays for heavy junkboxes stolen from dangerous targets across Azeroth, and accepts them in batches. Only skilled thieves can lift the boxes from their marks in the wild, but anyone may bring them to the manor. Even boxes stripped of major valuables earn his favor and finely balanced throwing knives from the manor. A token coin must remain inside, to motivate the initiates.",sp=0}},faq={{q="Why does Fahrad want these junkboxes?",a="Ravenholdt's apprentice rogues need realistic locks to practice on. Zan, the manor's resident craftsman, makes practice chests that Fahrad considers too elementary for anyone past the beginner stage. So he requires real lockboxes taken from dangerous marks.",al={"why junkboxes","junkboxes purpose","why fahrad wants boxes"},it="motive"},{q="Where does this task take place?",a="The exchange takes place at Ravenholdt Manor, a secret refuge for the thieves' guild in the mountains north of Hillsbrad Foothills.",al={"junkboxes needed location","where is fahrad","ravenholdt location"},it="place",gp=true},{q="Can only rogues turn in this quest?",a="Anyone who brings heavy junkboxes to the manor may deliver them. Skilled thieves steal the boxes from their marks through pickpocketing.",al={"is this rogue only","can anyone do junkboxes needed","other classes junkboxes"},it="why_me",gp=true},{q="Why must there still be coins left inside the boxes?",a="Fahrad requires a few coins to remain in each chest, giving rogues in training a practical reason to practice their lockpicking.",al={"why leave coins in box","do boxes need loot","empty junkboxes"},it="purpose"},{q="What does Ravenholdt offer in exchange?",a="Contributors earn guild standing and finely crafted throwing knives from Fahrad. He sardonicly hopes they find a place in someone's heart.",al={"junkboxes needed reward","what does fahrad give","ravenholdt throwing knives"},it="for_you"},{q="Who is Zan that Fahrad complains about?",a="Zan supplies Ravenholdt with locks and practice mechanisms. Fahrad finds Zan's crude work fit only for the rawest beginners, not serious operatives.",al={"who is zan","zan ravenholdt","zan locks"},it="people"},{q="Why does Ravenholdt need an outside rogue to gather junkboxes?",a="Ravenholdt's current trainees are still cutting their teeth and simply lack the skill to obtain intricate locks on their own. The practice mechanisms crafted by their in-house tinker, Zan, are far too crude for advanced training. Fahrad relies on accomplished operatives like you to venture into perilous territory and filch genuine, high-security lockboxes that pose a real challenge.",al={"why ask me for junkboxes","why winstone wolfe needs me","why doesn't ravenholdt get their own junkboxes"},it="why_me",add="45d1fe22"}},ang={["class:Rogue"]="As a rogue, you can get these heavy chests by pickpocketing seasoned adversaries. Ravenholdt gives that illicit skill a place to serve.",["faction:Alliance"]="Ravenholdt lies in contested Lordaeron territory and operates independently. As an Alliance wanderer, you can bring it contracts without regard for faction lines.",["faction:Horde"]="As a Horde operative, you can brave the trek into the Hillsbrad mountains. Ravenholdt is indifferent to faction loyalties and prizes useful illicit goods above all else."},kw={"heavy junkbox","hillsbrad","junkboxes","lockpicking","pickpocket","ravenholdt","fahrad","zan"},rel={"topic:ravenholdt","zone:hillsbrad"},m={start="Fahrad",["end"]="Fahrad",cl={"ROGUE"},id=8249},src={"Junkboxes Needed"}}
E["quest:94912"] = {t="quest",n="Child of Nature",z="alterac",s="In Stormwind, Sheldras Moontree can show you the way to Moonglade. There, the Cenarion Circle’s druids have wisdom to share with a child of nature.",h="In Stormwind, Sheldras Moontree can show you the way to Moonglade.",sec={{t="A Far Stronghold",b="Sheldras Moontree, a night elf in Stormwind, can show you how to reach Moonglade on Kalimdor. The Cenarion Circle keeps its stronghold there. It is an ancient order of naturalists and druids, with much to teach you.",sp=0}},faq={{q="Who is Sheldras Moontree?",a="Sheldras Moontree is a night elf in Stormwind who can show you how to reach Moonglade.",al={"sheldras","night elf in stormwind","who teaches me moonglade"}},{q="What is the Cenarion Circle?",a="The Cenarion Circle is an ancient order of naturalists and practitioners of the druidic arts.",al={"cenarion circle","druid order","nature circle"}},{q="Where is the Cenarion Circle's stronghold?",a="The Cenarion Circle keeps its stronghold in Moonglade on Kalimdor.",al={"cenarion stronghold","where is moonglade","moonglade"}},{q="What can I learn from the Cenarion Circle?",a="The Cenarion Circle’s druids have much wisdom to share with you.",al={"cenarion teachings","what can they teach","druid wisdom"}}},ang={["race:Skyborne"]="As a Skyborne, you are among the first of your people to arrive in Azeroth, and you are welcomed.",["class:Druid"]="As a druid, you are directed toward the Cenarion Circle, an ancient order whose members practice the druidic arts."},kw={"cenarion circle","child of nature","druid","kalimdor","moonglade","sheldras moontree","skyborne","stormwind"},rel={"quest:5921","topic:cenarion-circle","quest:94911"},m={faction="Alliance",cl={"DRUID"},id=94912},src={"In-game quest text: Child of Nature"},fv=true}
E["quest:94947"] = {t="quest",n="Welcome to Azeroth",z="alterac",s="You arrive in Stormwind through the Skyborne Portal and are welcomed by its regent. Highlord Bolvar Fordragon grants you leave to travel across Alliance lands.",h="You arrive in Stormwind through the Skyborne Portal and are welcomed by its regent.",sec={{t="Arrival in the Capital",b="You step through the Skyborne Portal into Stormwind, the human capital. From there, you make your way along the city's grand thoroughfares to Stormwind Keep, where the regency awaits your arrival.",sp=0},{t="An Audience with the Regent",b="Highlord Bolvar Fordragon receives the arriving members of the High Order in the throne room. A Kirin Tor courier had warned him they were coming. It has been some time since high elves walked the halls of Stormwind Keep, yet Bolvar welcomes them as guests and grants them free passage across Alliance territories on behalf of the King.",sp=0}},faq={{q="What is this quest about?",a="You arrive in Stormwind through the Skyborne Portal and present yourself to Highlord Bolvar Fordragon at Stormwind Keep.",al={"what is welcome to azeroth","welcome to azeroth quest"}},{q="Who is Bolvar Fordragon?",a="Highlord Bolvar Fordragon governs Stormwind as regent from Stormwind Keep. He rules on behalf of the young King Anduin Wrynn while King Varian remains missing.",al={"who is bolvar fordragon","regent of stormwind"}},{q="Why is Bolvar receiving the Skyborne?",a="A Kirin Tor messenger told Bolvar Fordragon that members of the High Order would arrive. He welcomes them as guests of the crown and grants them leave to travel freely across Alliance lands.",al={"why are skyborne in stormwind","high elves stormwind"}},{q="What is the High Order?",a="The High Order is the group associated with the Skyborne high elves. The Kirin Tor announced their arrival to Stormwind's leaders.",al={"who is high order","high order lore"}},{q="Where does the Skyborne Portal lead?",a="The Skyborne Portal brings travelers directly into Stormwind, the human capital. From there, newcomers can go to Stormwind Keep to seek an audience with the crown.",al={"skyborne portal destination","where does portal go"}},{q="Are the Skyborne allowed throughout Alliance territory?",a="Bolvar Fordragon welcomes the Skyborne as the King's guests and grants them leave to travel unhindered throughout Alliance lands.",al={"are skyborne alliance","skyborne welcome alliance"}}},ang={["race:Skyborne"]="As a Skyborne, you are welcomed into Stormwind and granted passage across Alliance territory when you arrive through the portal.",["faction:Alliance"]="Highlord Bolvar Fordragon officially welcomes the High Order on behalf of King Anduin Wrynn, granting them leave to freely traverse Alliance lands."},kw={"bolvar fordragon","high elf","high order","kirin tor","portal","skyborne","stormwind keep","welcome to azeroth"},rel={"npc:bolvar-fordragon","subzone:stormwind-keep","topic:skyborne","quest:92596","topic:alliance","topic:stormwind-kingdom","quest:95350"},m={faction="Alliance",id=94947},src={"In-game quest text: Welcome to Azeroth"},fv=true}
E["quest:96603"] = {t="quest",n="Unstable Magic",z="alterac",s="Archmage Celindra in Dalaran seeks field data for Archmage Rhonin, who is investigating a disturbance in Azeroth's magic. You are asked to gather motes of unstable magic with an Arcane Censer.",h="Archmage Celindra in Dalaran seeks field data for Archmage Rhonin, who is investigating a disturbance in...",sec={{t="Field Data",b="Archmage Rhonin is abroad, studying a disturbance in the flow of magic across Azeroth. In Dalaran, Archmage Celindra asks you to gather motes that may aid his investigation. The Arcane Censer lets you draw them from skilled spell casters and other powerful beings; the Kirin Tor awaits the gathered data.",sp=0}},faq={{q="Who is asking for the motes?",a="Archmage Celindra in Dalaran asks you to gather motes of unstable magic for Archmage Rhonin.",al={"who wants motes","celindra task","who is celindra"}},{q="Why does Rhonin need the motes?",a="Rhonin is investigating a disturbance in the flow of magic across Azeroth, and the motes provide field data for his work.",al={"why motes","rhonin magic study","what is rhonin investigating"}},{q="What does the Arcane Censer do?",a="While its magic affects you, the Arcane Censer lets you extract motes of unstable magic from skilled spell casters and other powerful beings.",al={"censer purpose","arcane censer","magic censer"}},{q="Where do I bring the motes?",a="Bring the motes to Archmage Celindra in Dalaran.",al={"where to take motes","dalaran motes","bring motes"}},{q="How many motes does Celindra ask for?",a="Celindra asks you to bring ten motes of unstable magic.",al={"mote count","how many motes","ten motes"}}},kw={"arcane censer","archmage celindra","archmage rhonin","dalaran","kirin tor","magic disturbance","motes","unstable magic"},rel={"subzone:dalaran"},m={faction="Alliance",id=96603},src={"In-game quest text: Unstable Magic"},fv=true}
E["quest:96770"] = {t="quest",n="The Witch Doctor's Head",z="alterac",s="Archmage Lan'dalock asks you to kill the Sandfury witch doctor Zum'rah in Zul'Farrak and bring back his intact head. The request rests on a history Lan'dalock shares with the troll.",h="Archmage Lan'dalock asks you to kill the Sandfury witch doctor Zum'rah in Zul'Farrak and bring back his...",sec={{t="Lan'dalock's Request",b="Archmage Lan'dalock in Dalaran wants Zum'rah dead. The witch doctor is inside Zul'Farrak, a Sandfury stronghold deep in Tanaris. Lan'dalock says he has history with Zum'rah, and asks you to return with the troll's head intact. His request turns on that old grievance.",sp=0}},faq={{q="Who is Zum'rah?",a="Zum'rah is a troll witch doctor inside Zul'Farrak, the Sandfury stronghold in Tanaris.",al={"zumrah","witch doctor zum'rah","sandfury witch doctor"}},{q="Who wants Zum'rah dead?",a="Archmage Lan'dalock in Dalaran asks you to kill Zum'rah. He says he has history with the troll.",al={"who gave this","lan'dalock","why kill zumrah"}},{q="Where is Zum'rah?",a="Zum'rah is inside Zul'Farrak, deep in the deserts of Tanaris.",al={"where find zumrah","zul'farrak","tanaris troll"}},{q="Why does Lan'dalock want him killed?",a="Lan'dalock says he has history with Zum'rah, but gives no further detail.",al={"lan'dalock grudge","why does archmage want zumrah dead","history with zumrah"}},{q="What does Lan'dalock ask you to bring back?",a="Lan'dalock asks you to bring him Zum'rah's head intact.",al={"bring back what","zumrah head","intact head"}}},kw={"dalaran","lan'dalock","sandfury","tanaris","troll","witch doctor","zul'farrak","zum'rah","zumrah"},rel={"subzone:zul-farrak","zone:tanaris","subzone:dalaran","quest:96775","topic:troll"},m={faction="Alliance",id=96770},src={"In-game quest text: The Witch Doctor's Head"},fv=true}
E["quest:96771"] = {t="quest",n="Vengeance of the Highborne",z="alterac",s="A patron asks you to find Zalfan Moonshadow at Krol'dok Stronghold in the Riverglades. He condemns Zalfan's ties to the Twilight's Hammer and use of stolen arcane knowledge.",h="A patron asks you to find Zalfan Moonshadow at Krol'dok Stronghold in the Riverglades.",sec={{t="A Highborne in the Glades",b="A patron points you southeast to Krol'dok Stronghold in the Riverglades, where Zalfan Moonshadow has been seen with the Twilight's Hammer. He calls Zalfan a disgrace to the Highborne, accusing him of serving fanatics with stolen arcane knowledge. The patron offers generous pay for Zalfan's death.",sp=0}},faq={{q="Who is Zalfan Moonshadow?",a="Zalfan Moonshadow is a Highborne seen at Krol'dok Stronghold with the Twilight's Hammer.",al={"zalfan","who's zalfan"}},{q="Where is Zalfan?",a="Zalfan has been seen at Krol'dok Stronghold in the Riverglades, southeast of here.",al={"where's zalfan","kroldok location"}},{q="Why does the patron want Zalfan dead?",a="The patron says Zalfan brings shame to the Highborne by consorting with the Twilight's Hammer and using stolen arcane knowledge in their service.",al={"why kill zalfan","zalfan problem"}},{q="What does the patron offer?",a="The patron offers generous pay to anyone who kills Zalfan Moonshadow.",al={"pay for zalfan","zalfan bounty"}}},kw={"highborne","krol'dok stronghold","riverglades","stolen arcane knowledge","twilight's hammer","vengeance of the highborne","zalfan moonshadow"},rel={"zone:riverglades","topic:highborne","topic:twilight-s-hammer"},m={faction="Alliance",id=96771},src={"In-game quest text: Vengeance of the Highborne"},fv=true}
E["quest:96772"] = {t="quest",n="The Dragon's Journal",z="alterac",s="Arcane scrying has uncovered a powerful magic user hiding in the sunken prison of Alcaz Island. A fleeting vision revealed a journal penned in ancient draconic script, and you are called to delve into the depths to retrieve it.",h="Arcane scrying has uncovered a powerful magic user hiding in the sunken prison of Alcaz Island.",sec={{t="Eyes on Alcaz",b="Magical scrying across the sea has pierced the defenses around Alcaz Island off Kalimdor. Before their arcane probes were unraveled by a rival spellcaster, Timear and his companion caught sight of a mysterious book. It is a journal written in ancient draconic script, kept by the powerful magic user dwelling within the island's underground prison. Now you are asked to descend into the island's depths and bring the volume back for study.",sp=0}},faq={{q="Where is the journal located?",a="The journal lies within the hidden prison beneath Alcaz Island off the coast of Kalimdor.",al={"where is the dragon journal","zarla journal location","where is the book"}},{q="What is the book?",a="It is a personal journal recorded in ancient draconic script, kept by a powerful magic user stationed in Alcaz Island's hidden prison.",al={"what is zarla journal","what kind of book is on alcaz"}},{q="Who discovered the journal's existence?",a="Timear and an allied spellcaster discovered the book by scrying Alcaz Island before their magical probes were dispelled.",al={"who found the book","who scried alcaz island"}},{q="Why are spellcasters investigating Alcaz Island?",a="Magical scrying confirmed the presence of a formidable magic user there who commands enough power to dispel arcane surveillance.",al={"why alcaz island","who is on alcaz island"}}},ang={["class:Mage"]="As a mage, you know the rarity of ancient draconic script. Uncovering how another spellcaster bends such magic can offer rare insight into forces few mortals understand."},kw={"alcaz island","alcaz prison","draconic script","kalimdor","the dragon's journal","timear","zarla's journal"},rel={"topic:mage"},m={faction="Alliance",id=96772},src={"In-game quest text: The Dragon's Journal"},fv=true}
E["quest:96773"] = {t="quest",n="The Coldbringer's Eye",z="alterac",s="The Kirin Tor seeks the Coldbringer’s Eye, a scrying orb used by a servant of the Lich King in Razorfen Downs. You are asked to recover it so the artifact can be studied.",h="The Kirin Tor seeks the Coldbringer’s Eye, a scrying orb used by a servant of the Lich King in Razorfen Downs.",sec={{t="A Kirin Tor Request",b="A servant of the Lich King dwells in Razorfen Downs, where the quilboar lair shelters him. The Kirin Tor says he uses the Coldbringer’s Eye to direct lesser minions elsewhere. You are asked to retrieve the orb for their study.",sp=0}},faq={{q="What is the Coldbringer’s Eye?",a="The Coldbringer’s Eye is a scrying orb used by a servant of the Lich King in Razorfen Downs.",al={"coldbringer eye","what's the eye","scrying orb"}},{q="Who wants the Coldbringer’s Eye?",a="The Kirin Tor wants the Coldbringer’s Eye so it can study the artifact and understand how it works.",al={"who wants the orb","kirin tor eye","who asked for it"}},{q="Where is the Coldbringer’s Eye?",a="The Coldbringer’s Eye is in Razorfen Downs.",al={"where's the eye","razorfen downs orb","eye location"}},{q="Who uses the orb?",a="A servant of the Lich King in Razorfen Downs uses the orb to direct lesser minions elsewhere.",al={"who has the eye","lich king servant","coldbringer user"}}},kw={"coldbringer","coldbringer's eye","kirin tor","lich king","quilboar","razorfen downs","scrying orb","servant"},rel={"subzone:razorfen-downs-classic","topic:razorfen","topic:quilboar","topic:lich-king"},m={faction="Alliance",id=96773},src={"In-game quest text: The Coldbringer's Eye"},fv=true}
E["quest:96779"] = {t="quest",n="Syndicate Sabotage",z="alterac",s="Myrokos Silentform sends you to Durnholde Keep to kill Lord Tomas. He expects Tomas's death to unsettle the Syndicate there.",h="Myrokos Silentform sends you to Durnholde Keep to kill Lord Tomas.",sec={{t="At Durnholde",b="At Durnholde Keep in Hillsbrad Foothills, Lord Tomas is the target Myrokos Silentform names. You are asked to kill him, then return to Myrokos.",sp=0},{t="The Keep's Order",b="Myrokos expects Tomas's death to leave the Syndicate thugs at Durnholde Keep without a leader and in disarray. He thanks you and may call on you again.",sp=1}},faq={{q="Who is Myrokos Silentform?",a="Myrokos Silentform asks you to find and kill Lord Tomas at Durnholde Keep, then return to him.",al={"who's myrokos","myrokos guy"}},{q="Who is Lord Tomas?",a="Lord Tomas is the target Myrokos names at Durnholde Keep.",al={"tomas who","lord tomas"}},{q="Why does Myrokos want Tomas dead?",a="Myrokos expects the Syndicate thugs at Durnholde Keep to fall into disarray without Tomas as their leader.",al={"why kill tomas","syndicate sabotage why"}},{q="Where is Lord Tomas?",a="Lord Tomas is inside Durnholde Keep in Hillsbrad Foothills.",al={"tomas location","where's tomas"}}},kw={"durnholde keep","hillsbrad foothills","lord tomas","myrokos silentform","syndicate","syndicate sabotage"},rel={"subzone:durnholde-keep","zone:hillsbrad","topic:syndicate"},m={id=96779},src={"In-game quest text: Syndicate Sabotage"},fv=true}
E["quest:96781"] = {t="quest",n="What's the Big Idea?",z="alterac",s="Myrokos Silentform at Ravenholdt Manor asks you to learn what the Syndicate seeks in the Ruins of Alterac. Barton carries the scouting reports that may reveal their purpose.",h="Myrokos Silentform at Ravenholdt Manor asks you to learn what the Syndicate seeks in the Ruins of Alterac.",sec={{t="Barton’s Report",b="At Ravenholdt Manor, Myrokos Silentform needs Barton's scouting report. A Syndicate party led by Barton prowls the Ruins of Alterac, searching for something. You are asked to take the report from him without killing him, so the Syndicate will not know its plans have drawn notice.",sp=0}},faq={{q="Who is Barton?",a="Barton leads a Syndicate scouting party prowling around the Ruins of Alterac.",al={"barton","who's barton","syndicate scout"}},{q="What is the Syndicate searching for?",a="The Syndicate party is searching for something in the Ruins of Alterac, but Myrokos needs Barton's scouting report to learn what.",al={"what are syndicate after","what are they looking for","syndicate search"}},{q="Why does Myrokos want the report?",a="Myrokos Silentform wants the report to learn what the Syndicate is searching for.",al={"why get report","barton's report","big idea"}},{q="Why not kill Barton?",a="If Barton dies, the Syndicate will realize they are being watched and may take steps to cover their tracks.",al={"don't kill barton","pickpocket barton","why steal report"}},{q="Where can Barton be found?",a="Barton is most likely among the Syndicate at Strahnbrad.",al={"where barton","find barton","strahnbrad scout"}},{q="Where does the report go?",a="Barton's scouting report is meant for Myrokos Silentform at Ravenholdt Manor.",al={"who gets report","bring report where","myrokos"}}},ang={["class:Rogue"]="As a rogue, you are asked to take Barton's report without killing him."},kw={"barton","myrokos silentform","ravenholdt manor","ruins of alterac","scouting report","strahnbrad","syndicate"},rel={"subzone:ravenholdt-manor","subzone:ruins-of-alterac","subzone:strahnbrad","topic:syndicate","topic:ravenholdt","topic:alterac-kingdom"},m={id=96781},src={"In-game quest text: What's the Big Idea?"},fv=true}
E["quest:96782"] = {t="quest",n="Covert Extraction",z="alterac",s="Myrokos Silentform seeks two Perenolde heirlooms in the ruins of Alterac. The Syndicate is after them too.",h="Myrokos Silentform seeks two Perenolde heirlooms in the ruins of Alterac.",sec={{t="The Heirlooms",b="In the ruins of Alterac, Myrokos Silentform wants you to recover two heirlooms of House Perenolde. The Blade of House Perenolde and the Royal Aegis of Perenolde lie in two towers, according to a report. The Syndicate seeks them as well, while ogres occupy the ruins. Myrokos asks you to bring both relics to him.",sp=0}},faq={{q="Who wants the Perenolde heirlooms?",a="Myrokos Silentform wants you to retrieve the Blade of House Perenolde and the Royal Aegis of Perenolde.",al={"who sent me","who wants these relics"}},{q="What are the two heirlooms?",a="They are the Blade of House Perenolde, a sword, and the Royal Aegis of Perenolde, a shield.",al={"perenolde relics","blade and shield"}},{q="Where are the heirlooms?",a="A report places the Blade of House Perenolde and the Royal Aegis of Perenolde in two towers among the ruins of Alterac.",al={"where are the relics","perenolde items location"}},{q="Why does Myrokos want them?",a="The Syndicate is also after the two Perenolde heirlooms, so Myrokos wants you to acquire them first.",al={"why retrieve the heirlooms","why does he need them"}},{q="Who occupies the ruins?",a="Ogres occupy the ruins of Alterac.",al={"ogres in alterac","what's in the ruins"}}},kw={"alterac","blade of house perenolde","covert extraction","myrokos silentform","ogres","royal aegis of perenolde","syndicate"},rel={"subzone:ruins-of-alterac","topic:syndicate","topic:alterac-kingdom"},m={id=96782},src={"In-game quest text: Covert Extraction"},fv=true}
E["quest:96783"] = {t="quest",n="A Way In",z="alterac",s="A Syndicate trade draws you toward Stromgarde Keep in the Arathi Highlands. You need a disguise from Northfold Manor to enter without suspicion.",h="A Syndicate trade draws you toward Stromgarde Keep in the Arathi Highlands.",sec={{t="A Hidden Trade",b="A contact sends you to Stromgarde Keep in the Arathi Highlands, where the Syndicate holds important dealings behind its walls. Word has reached them of a trade between Syndicate members, and its details may be inside the keep. To enter without arousing suspicion, you need a Syndicate uniform from Northfold Manor.",sp=0}},faq={{q="What is happening at Stromgarde Keep?",a="The Syndicate uses Stromgarde Keep as one of its largest strongholds, and a trade between its members is taking place somewhere in the Arathi Highlands.",al={"stromgarde trade","what's at stromgarde","syndicate keep"}},{q="Why am I going to Northfold Manor?",a="You are looking for a Syndicate uniform at Northfold Manor to disguise yourself before entering Stromgarde Keep.",al={"northfold manor","why northfold","get disguise"}},{q="What do I need to enter the keep?",a="You need a Syndicate uniform from Northfold Manor to enter Stromgarde Keep without arousing suspicion.",al={"uniform","syndicate disguise","way into stromgarde"}},{q="What is the Syndicate trade about?",a="The trade is between Syndicate members somewhere in the Arathi Highlands. Its details may be found inside Stromgarde Keep.",al={"syndicate deal","what trade","trade details"}}},kw={"a way in","arathi highlands","northfold manor","stromgarde keep","syndicate","trade","uniform"},rel={"subzone:northfold-manor","subzone:stromgarde-keep","zone:arathi","topic:syndicate"},m={id=96783},src={"In-game quest text: A Way In"},fv=true}
E["quest:96800"] = {t="quest",n="Past Due",z="alterac",s="A scholar needs a missing tome from the Scarlet Monastery to study Grim Batol’s ancient Wildhammer runemasters.",h="A scholar needs a missing tome from the Scarlet Monastery to study Grim Batol’s ancient Wildhammer...",sec={{t="An overdue book",b="The old Dalaran library’s ledgers show that Arcanist Doan borrowed the tome before the Third War and never returned it.",sp=0}},faq={{q="Who needs the book?",a="A scholar writing a thesis on the ancient Wildhammer runemasters of Grim Batol needs the book for that research.",al={"who wants the tome","scholar research"}},{q="What book was borrowed?",a="The borrowed book is called The Lost Magic of the Runemasters.",al={"which tome","lost runemasters book"}},{q="Who borrowed the book?",a="The old Dalaran library’s ledgers say a mage named Doan borrowed the book before the Third War.",al={"who checked it out","Doan book"}},{q="Where is the book?",a="The book is in the Scarlet Monastery in Tirisfal Glades, where Arcanist Doan is now.",al={"where's the tome","book location"}},{q="What is the research about?",a="The scholar is researching the ancient Wildhammer runemasters of Grim Batol.",al={"wildhammer runemasters","Grim Batol thesis"}}},kw={"arcanist doan","dalaran library","grim batol","past due","scarlet monastery","the lost magic of the runemasters","wildhammer runemasters"},rel={"subzone:grim-batol","zone:scarlet","zone:tirisfal","subzone:dalaran","topic:mage"},m={faction="Alliance",id=96800},src={"In-game quest text: Past Due"},fv=true}
E["quest:97130"] = {t="quest",n="Ancient Gurubashi Secrets",z="alterac",s="Lan'dalock and a companion ask you to recover an idol from an ancient Gurubashi ruin newly risen off Stranglethorn Vale. The site may hold valuable clues to Gurubashi blood magic.",h="Lan'dalock and a companion ask you to recover an idol from an ancient Gurubashi ruin newly risen off...",sec={{t="A Ruin Risen",b="Lan'dalock and a companion have been discussing a strange change in the South Seas. An ancient Gurubashi ruin has appeared off Stranglethorn Vale's coast. Its sudden return draws the interest of those who study the past.",sp=0},{t="An Idol of the Gurubashi",b="The Drowned City holds artifacts of great archaeological worth. Lan'dalock seeks an idol once used by certain Gurubashi witch doctors as a focus for blood magic. You are asked to bring one back for study.",sp=0}},faq={{q="Who wants the idol?",a="Lan'dalock and a companion seek an Ancient Gurubashi Idol from the Drowned City.",al={"who sent me","lan'dalock idol","who wants it"}},{q="Where did the Gurubashi ruin appear?",a="The ancient Gurubashi ruin appeared off the coast of Stranglethorn Vale in the South Seas.",al={"where is drowned city","ruin location","gurubashi city"}},{q="Why do they want an idol?",a="Certain ancient Gurubashi witch doctors used idols as focuses for blood magic, and Lan'dalock wants one for study.",al={"why idol","idol purpose","what is it for"}},{q="What is the Drowned City?",a="It is an ancient Gurubashi ruin that has appeared off Stranglethorn Vale's coast.",al={"drowned city","sunken gurubashi ruins","ancient ruins"}}},kw={"ancient gurubashi idol","ancient gurubashi secrets","blood magic","drowned city","gurubashi","lan'dalock","south seas","stranglethorn vale","witch doctors"},rel={"quest:96774","quest:95775","zone:stranglethorn","subzone:south-seas"},m={faction="Alliance",id=97130},src={"In-game quest text: Ancient Gurubashi Secrets"},fv=true}
E["quest:98895"] = {t="quest",n="Darkspear Islands Clash",z="alterac",s="Across the Darkspear Islands, Alliance forces are hard pressed. Without help at the front, they risk losing the whole archipelago to the fierce Darkspear Raiders.",h="Across the Darkspear Islands, Alliance forces are hard pressed.",sec={{t="A Contested Front",b="Open war now rages across the Darkspear Islands between the Alliance and the aggressive Darkspear Raiders. Alliance commanders fear their foothold in the archipelago will be overwhelmed without urgent reinforcements. So they call capable champions to the front to stem the attack.",sp=0},{t="Proof of Valor",b="Alliance commanders need proven fighters willing to serve on the front lines. Warriors bring back Darkspear Islands Marks of Honor as proof of their service. The marks uphold discipline and honor those whose courage turns the battle.",sp=0}},faq={{q="What is Darkspear Islands Clash?",a="Alliance officers overseeing the fighting call champions to face the Darkspear Raiders. Warriors prove their service by recovering marks of honor from the battle.",al={"what is darkspear islands clash","clash quest","darkspear islands battle"}},{q="Who are the Darkspear Raiders?",a="The Darkspear Raiders are troll warbands fighting for control of the Darkspear Islands. Their fierce attacks threaten Alliance footholds and prompt urgent calls for reinforcements.",al={"who are darkspear raiders","darkspear raider enemy","who are we fighting in darkspear islands"}},{q="Why is the Alliance fighting on the Darkspear Islands?",a="The Alliance fights to hold strategic ground in the Darkspear Islands and keep the region from falling under troll control. Losing ground would weaken Alliance influence and security across the contested coastal waters.",al={"why alliance fighting darkspear islands","why fight here","alliance darkspear war"}},{q="Who issues and completes this mission?",a="An Alliance Brigadier General stationed outside the battlegrounds oversees troop mobilization and receives returning champions' proof of battlefield service.",al={"who gives darkspear islands clash","who takes darkspear marks of honor","alliance brigadier general location"}},{q="What are Darkspear Islands Marks of Honor?",a="Darkspear Islands Marks of Honor are military tokens for valor and active service on the front line. Warriors present three marks to an Alliance Brigadier General as proof of their service in battle.",al={"what are marks of honor","darkspear islands mark of honor","how to prove front line service"}},{q="What is at stake if the Alliance fails?",a="Without rapid reinforcements, relentless Darkspear Raider attacks could bring Alliance positions on the Darkspear Islands to complete collapse. Holding the islands keeps hostile forces from claiming unchallenged dominance over the archipelago.",al={"what happens if alliance loses darkspear islands","why urgent aid needed","losing darkspear islands"}}},ang={["faction:Alliance"]="Alliance high command calls champion volunteers to reinforce the front against the Darkspear Raiders and protect strategic positions in the islands.",["class:Warrior"]="As a warrior, you bear the brunt of the assault against fierce troll raiders. Your discipline and valor can turn the tide of battle.",["class:Paladin"]="As a paladin, you bring resolve to the violent clashes, answering the Alliance call to protect its people and repel hostile forces."},kw={"alliance","battleground","brigadier general","darkspear islands","darkspear islands clash","darkspear raiders","marks of honor"},rel={"zone:darkspearislands","topic:alliance"},m={faction="Alliance",id=98895},src={"In-game quest text: Darkspear Islands Clash"},fv=true}
E["quest:98896"] = {t="quest",n="Darkspear Islands Clash",z="alterac",s="Fighting rages across the Darkspear Islands Clash as Darkspear Raiders contest the archipelago. Fighters are called to rally their companions and stop enemy incursions across the islands.",h="Fighting rages across the Darkspear Islands Clash as Darkspear Raiders contest the archipelago.",sec={{t="The Archipelago at War",b="Darkspear Raiders skirmish across the beaches and interior of the islands. Forces sent there are urged to hold their ground as the campaign to secure a foothold in the archipelago continues.",sp=0},{t="Rallying the Front Line",b="Commanders on the front line call for fighters to gather against the resilient raiders. Survival and victory depend on rallying nearby allies into a force that can withstand counterattacks. Together, they can rout fortified raiding bands and break their hold on the disputed island strongholds.",sp=0}},faq={{q="What is the Darkspear Islands Clash?",a="Fighters are called to rally their allies and attack the Darkspear Raiders amid ongoing fighting across the Darkspear Islands.",al={"what is this quest","darkspear islands clash summary","clash quest info"}},{q="Where does this fight take place?",a="The fighting takes place across the Darkspear Islands, an archipelago marked by territorial struggles and clashes at sea.",al={"where does this happen","where are darkspear islands","clash location"}},{q="Who are the Darkspear Raiders?",a="The Darkspear Raiders are the Horde's troll defenders of the Darkspear Islands, the sacred isles of Vol'jin's tribe. Combatants are ordered to defeat them as they contest territory across the islands.",al={"who are the enemies","who do we fight","darkspear raiders target"}},{q="Why must forces be rallied for this clash?",a="Allied forces must gather to withstand sustained counterattacks and break the raiders' lines.",al={"why rally forces","what is the goal","how to complete clash"}},{q="Why does the fight in the Darkspear Islands continue?",a="The Horde and Alliance continue to struggle for the islands' strongpoints. The Horde guards them as sacred troll ground, while the Alliance seeks a foothold off Kalimdor's shore.",al={"why is there fighting","why conflict in islands","island battle cause"}},{q="Who directs the forces in this engagement?",a="The Alliance Brigadier General in the Alterac Mountains directs the forces. He urges soldiers on the ground to push forward without wavering.",al={"who gives this quest","quest giver clash","clash commander"}}},ang={["race:Troll"]="As a troll, you know the Darkspear Raiders targeted by this Alliance order are Vol'jin's own people. They defend their tribe's sacred isles.",["faction:Horde"]="As a member of the Horde, you face the Alliance side of the fight for the Darkspear Islands. The Horde holds these sacred troll isles off Kalimdor's coast against outsiders."},kw={"clash","darkspear islands","darkspear raiders","islands conflict","rally","skirmish","troll raiders"},rel={"zone:darkspearislands"},m={id=98896},src={"In-game quest text: Darkspear Islands Clash"},fv=true}
E["quest:99191"] = {t="quest",n="A Donation of Wool",z="alterac",s="The High Order is taking wool cloth from those who seek its full recognition. Sixty pieces meet its current need.",h="The High Order is taking wool cloth from those who seek its full recognition.",sec={{t="A Worthy Gift",b="The High Order is accepting wool cloth, and sixty pieces meet its current needs. The giver can take your donation now. In return, the order grants you full recognition.",sp=0}},faq={{q="What does the High Order need?",a="The High Order needs wool cloth, and sixty pieces meet its current need.",al={"high order wool","what to donate","wool donation"}},{q="How much wool cloth should I give?",a="Give sixty pieces of wool cloth to earn full recognition from the High Order.",al={"how much wool","sixty wool","wool amount"}},{q="Who can take the donation?",a="The giver can accept your sixty pieces of wool cloth.",al={"who takes wool","donation giver","give wool"}},{q="What do I gain by donating?",a="Giving sixty pieces of wool cloth earns you full recognition from the High Order.",al={"wool recognition","high order standing","donation benefit"}}},kw={"donation","high order","recognition","sixty pieces","wool","wool cloth"},rel={"quest:92596"},m={faction="Alliance",id=99191},src={"In-game quest text: A Donation of Wool"},fv=true}
E["subzone:dalaran"] = {t="subzone",n="Dalaran",z="alterac",s="On Lordamere Lake, Dalaran's surviving magi are rebuilding their shattered city. Once the shining capital of the Kirin Tor, it fell to the Scourge and Archimonde during the Third War. Its protective violet shield has been removed.",h="On Lordamere Lake, Dalaran's surviving magi are rebuilding their shattered city.",sec={{t="Fall of the Magocracy",b="Dalaran began as a sanctuary for arcane study, founded by sorcerers of the Arathorian Empire after the ancient Troll Wars. For centuries, it was humanity's foremost center of magic. The Council of Six led the Kirin Tor, keeping vast archives and powerful artifacts in the Violet Citadel.\n\nThat age ended during the Third War. The traitor prince Arthas led the Scourge through the city gates to seize the Book of Medivh. Soon after, the demon lord Archimonde crushed Dalaran's soaring spires into rubble.",sp=0},{t="Rebuilding the Magocracy",b="After the Legion's defeat, the Kirin Tor's surviving wizards returned to their devastated homeland. They would not yield their ancestral ground to the Scourge or scavengers, and raised a shimmering violet barrier over the city's heart. The shield has since been removed, while rebuilding continues. The magi are restoring their fallen sanctuary, and Archmage Ansirem Runeweaver can be found in the Violet Citadel.",sp=0}},faq={{q="What became of Dalaran's protective shield?",a="After Dalaran's destruction in the Third War, the Kirin Tor raised a magical shield over the city. The shield has since been removed, and rebuilding continues.",al={"purple bubble","purple shield alterac","what is the dome","dalaran dome"}},{q="Can players enter Dalaran?",a="Yes. Reconstruction is underway, and Archmage Ansirem Runeweaver resides in the Violet Citadel. The Kirin Tor sides with the Alliance, and the Horde is Hated by them and attacked on sight in the city. Horde groups can still enter the City of Dalaran dungeon.",al={"can i get inside dalaran","how to enter dalaran","get past dalaran shield"}},{q="Who destroyed Dalaran?",a="Prince Arthas and his Scourge army attacked Dalaran and stole the Book of Medivh from its vaults. Soon after, the demon lord Archimonde used dark sorcery to pulverize the city into ruins.",al={"how did dalaran fall","who blew up dalaran","why is dalaran in ruins"}},{q="Who rules Dalaran?",a="The Kirin Tor governs Dalaran through its ruling assembly, the Council of Six.",al={"who runs dalaran","dalaran leadership","who leads kirin tor"}}},ang={["class:Mage"]="As a mage, you look to Dalaran as the historic cradle of human and high elven wizardry. Its legendary spires are still being rebuilt, a solemn reminder of the losses mages suffered in the Third War.",["faction:Alliance"]="As an Alliance member, you can trace Dalaran's place in your history to its role as one of the seven founding kingdoms of the original Alliance of Lordaeron. The Kirin Tor is rebuilding its devastated capital."},kw={"alterac","archimonde","council of six","dalaran","dome","kirin tor","lordamere","shield","violet citadel"},rel={"zone:alterac","subzone:lordamere-lake","topic:third-war","topic:scourge","topic:burning-legion","topic:lordaeron"},src={"Dalaran"}}
E["subzone:dandred-s-fold"] = {t="subzone",n="Dandred's Fold",z="alterac",s="Syndicate outlaws hold Dandred's Fold on Lordamere Lake's northwestern shore. The farmstead and manor shelter Lord Aliden Perenolde and his co-conspirators. The Horde and Alliance watch the estate for different reasons.",h="Syndicate outlaws hold Dandred's Fold on Lordamere Lake's northwestern shore.",sec={{t="A Noble Safe Haven Fallen to Outlaws",b="On the western edge of the Uplands, Dandred's Fold stands beside Lordamere Lake, apart from the surrounding country. The estate was once tranquil and may have belonged to an Alteraci noble named Dandred. After Alterac fell, the Syndicate turned it into a fortified refuge. Its assassins and enforcers patrol the grounds. They keep Southshore authorities and the Forsaken across the lake from the fallen nobility sheltered within.",sp=0},{t="A Nexus of Intrigues",b="Lord Aliden Perenolde leads the Syndicate and makes Dandred's Fold his base. His mistress, Elysa, is with him there. Nagaz has also made his place at the manor. A rogue Shadow Council orc of the Argus Wake, he brokers dark pacts with the human brigands. This alliance has drawn the attention of Southshore's magistrates and Horde champions.",sp=1}},faq={{q="Who controls Dandred's Fold?",a="The Syndicate occupies Dandred's Fold. It is an aristocratic criminal network led by Alterac's deposed nobles, and its assassins and enforcers guard the estate under Lord Aliden Perenolde.",al={"who is at dandreds fold","who lives at dandred's fold","dandreds fold mobs"},it="residents"},{q="Why does the Horde care about this estate?",a="The Horde targets the manor to strike down Lord Aliden Perenolde and retrieve a stolen keepsake. It is the heirloom necklace of Taretha Foxton, Thrall's childhood savior and confidante.",al={"horde dandreds fold","why horde go to dandreds fold"},sp=1,it="conflict",bt={"q533.6"}},{q="Why does the Alliance send adventurers here?",a="Magistrate Henry Maleb of Southshore sends Alliance agents to eliminate Nagaz. He is a dangerous member of the Argus Wake cult who colludes with the Syndicate outlaws.",al={"alliance dandreds fold","magistrate maleb quest dandreds fold"}},{q="Who was Dandred?",a="No confirmed account identifies Dandred. The estate bears his name, but its original owner is unknown.",al={"who is dandred","dandred lore"},it="name"},{q="What is Dandred's Fold?",a="Dandred's Fold is a secluded farm and manor perched on the western Uplands of the Alterac Mountains, bordering the misty shores of Lordamere Lake. Once a peaceful noble estate, it now serves as a fortified haven and operational base for the Syndicate.",al={"what is dandreds fold","dandreds fold alterac","about dandreds fold"},it="place",add="e469c160"},{q="What happened at Dandred's Fold?",a="Following the collapse of the Kingdom of Alterac, this lakeside farm fell into the hands of the Syndicate. Lord Aliden Perenolde turned the isolated manor into a personal stronghold and retreat, forging dangerous ties with shadowy organizations like the Argus Wake.",al={"dandreds fold history","what happened to dandreds fold"},it="history",add="b8b5cedb"},{q="Is Dandred's Fold dangerous?",a="It is extremely hazardous for lone travelers. The grounds are guarded by skilled Syndicate enforcers, stealthy cutthroats, and covert agents of the Argus Wake, all fiercely loyal to Lord Aliden Perenolde and hostile to outside intruders.",al={"is dandreds fold dangerous","dandred fold danger","who is at dandreds fold"},it="danger",add="fc1f4fab"}},ang={["faction:Horde"]="For the Horde, Dandred's Fold is personal. Warchief Thrall seeks the return of Taretha Foxton's necklace.",["faction:Alliance"]="The Alliance cannot tolerate an alliance between human outlaws and the demonic Argus Wake. Magistrate Henry Maleb orders strikes against the estate."},kw={"aliden perenolde","argus wake","dandred's fold","dandreds fold","elysa","lordamere lake","nagaz","syndicate","uplands"},rel={"topic:syndicate","zone:alterac","npc:magistrate-henry-maleb","subzone:uplands","subzone:lordamere-lake","subzone:misty-shore","topic:alterac-kingdom","topic:alliance"},src={"Dandred's Fold"}}
E["subzone:lordamere-internment-camp"] = {t="subzone",n="Lordamere Internment Camp",z="alterac",s="Surviving Dalaran magi and guards hold Lordamere Internment Camp above Dalaran. The old prison also shelters Forsaken defectors.",h="Surviving Dalaran magi and guards hold Lordamere Internment Camp above Dalaran.",sec={{t="From Prison to Research Outpost",b="Lordamere Internment Camp now serves Dalaran’s remnants as a research outpost. After the Second War, the Alliance built camps across the northern kingdoms to hold the defeated orcish Horde. Lordamere was the only camp in the Alterac Mountains, and Dalaran oversaw it. The orcs have long since been freed or fled. Warden Belamoore leads the camp, where Dalaran’s survivors study dangerous magical relics.",sp=0},{t="Forsaken Defectors",b="Four Forsaken renegades, including Kegan Darkmar, fled to Lordamere with Bloodstone artifacts stolen from the Undercity. They traded the relics to Warden Belamoore for sanctuary behind Dalaran’s lines. The magi accepted them for arcane study. In Tarren Mill, executors send loyal Horde operatives to hunt the defectors and recover the stolen Bloodstones before Dalaran unlocks their power.",sp=1}},faq={{q="What was this camp originally built for?",a="After the Second War, the Alliance built the camp to imprison orcs who had grown lethargic after losing their demonic bloodlust. Dalaran manned its watchtowers and oversaw it because it stood so close to the magi’s city.",al={"internment camp history","why is there a camp here","what is this place"}},{q="Who controls the camp right now?",a="Warden Belamoore and a detachment of Dalaran guards and magi hold the camp. Though Dalaran suffered heavy damage, its survivors continue their research from the fortified hilltop.",al={"who lives here","who runs the camp","who is warden belamoore"}},{q="Why are there undead Forsaken inside the camp?",a="Kegan Darkmar leads the deserters from the Undercity. They betrayed Queen Sylvanas and stole sacred Bloodstone artifacts, then traded the relics to Warden Belamoore for protection from Forsaken retribution.",al={"undead here","kegan darkmar","forsaken deserters"}}},ang={["race:Undead"]="The deserters at Lordamere have betrayed the Dark Lady. Hunting Kegan Darkmar and recovering the Bloodstones is vital to keeping Forsaken secrets from human hands.",["race:Orc"]="For orcs, Lordamere recalls the years after the Second War, when thousands of their kin withered in captivity before Thrall rallied their people."},kw={"alterac","belamoore","bloodstone","dalaran","internment","kegan darkmar","lordamere","orcs"},rel={"zone:alterac","subzone:dalaran","topic:second-war","topic:forsaken","topic:horde"},src={"Lordamere Internment Camp"}}
E["subzone:misty-shore"] = {t="subzone",n="Misty Shore",z="alterac",s="Along Lordamere Lake's eastern bank, Misty Shore lies between Dandred's Fold and Dalaran. Fog softens the view across the water, where the Dawning Isles and Fenris Keep rise in the distance.",h="Along Lordamere Lake's eastern bank, Misty Shore lies between Dandred's Fold and Dalaran.",sec={{t="A Fog-Shrouded Waterline",b="Misty Shore is a lakeside stretch of the Alterac Mountains, running up to Dalaran's perimeter. Damp air drifts off the water, often hiding snapping turtles along the shore. Zealous fanatics sometimes wander down from nearby strongholds.",sp=0},{t="Watching the Lake",b="Across Lordamere Lake, the Dawning Isles and Fenris Keep rise through the fog. Dalaran lies nearby, with Scarlet-controlled pockets close at hand. Travelers keep a low profile along the bank to avoid unwanted attention.",sp=0}},faq={{q="Where is the Misty Shore located?",a="Misty Shore follows the eastern shore of Lordamere Lake in the Alterac Mountains, between Dandred's Fold and Dalaran's perimeter.",al={"misty shore location","where is misty shore","misty shore map"},it="place"},{q="What can be seen across the water from here?",a="From the shore you can make out the Dawning Isles and Fenris Keep across Lordamere Lake, half hidden in fog.",al={"what is across the water","misty shore view","lake view"}},{q="What threats are typically found along the shore?",a="Snapping turtles inhabit the shoreline. Travelers may also encounter Scarlet Crusade zealots or scouts from nearby farmsteads and ruins.",al={"misty shore danger","enemies at misty shore","creatures on misty shore"},it="threat"},{q="What is Misty Shore?",a="Misty Shore is a quiet, fog-shrouded stretch of shoreline bordering the eastern shore of Lordamere Lake in the Alterac Mountains. It extends roughly between Dandred's Fold and the perimeter of Dalaran, offering a clear view across the lake toward the Dawning Isles and the distant towers of Fenris Keep.",al={"what is misty shore","about misty shore","misty shore overview"},it="place",add="140433c1"},{q="Is Misty Shore dangerous?",a="While it appears placid at first glance, the shore is far from safe. The waters and banks teem with aggressive snapjaw turtles, and travelers must watch for hostile humans aligned with the Scarlet Crusade who patrol nearby, attacking anyone they perceive as tainted or trespassers.",al={"how dangerous is misty shore","misty shore dangers","is misty shore safe"},it="danger",add="fbe1f33b"}},ang={["profession:Cooking"]="Snapping turtles along Lordamere Lake provide meat for cooks traveling through Alterac.",["faction:Horde"]="The misty bank offers a sheltered approach between Forsaken-held lands near Tarren Mill and the northern lakeshore, away from open patrols."},kw={"alterac mountains","dandred's fold","dawning isles","fenris keep","lordamere lake","misty shore","turtles"},rel={"subzone:lordamere-lake","zone:alterac","subzone:dandred-s-fold","subzone:fenris-isle","subzone:fenris-keep","subzone:dawning-isles","topic:scarlet-crusade"},src={"Misty Shore"}}
E["subzone:ruins-of-alterac"] = {t="subzone",n="Ruins of Alterac",z="alterac",s="Snow lies over the Ruins of Alterac, where Crushridge ogres now hold the old mountain capital. After King Aiden Perenolde betrayed the Alliance in the Second War, Alterac was cast out and placed under martial law.",h="Snow lies over the Ruins of Alterac, where Crushridge ogres now hold the old mountain capital.",sec={{t="A Kingdom's Betrayal",b="Alterac once ruled as an independent human realm, carved from the old Arathor empire and set high on mountain trade routes. During the Second War, King Aiden Perenolde feared the invading Old Horde would destroy his kingdom, so he secretly made a pact with the orcs. After the fighting at Caer Darrow, the betrayal came to light. The Alliance of Lordaeron struck swiftly.\n\nKing Terenas Menethil II placed the city under martial law and deposed Perenolde. The people fled or turned to outlawry, and the grand fortifications, church, and palace fell into disrepair.",sp=0},{t="The Ogre Occupation",b="Surviving Alteraci nobles and rogue soldiers formed the Syndicate. They waged guerrilla campaigns from towns like Strahnbrad, but lost their ancestral capital. Today, Crushridge ogres under Mug'thol dwell among broken ramparts, palace halls, and wrecked ballistae. Neither the Syndicate nor Southshore's human defenders have reclaimed the fallen city.\n\nIts crumbling towers and abandoned vaults remain dangerous ground for treasure hunters and scavengers.",sp=0}},faq={{q="Why was Alterac destroyed?",a="During the Second War, King Aiden Perenolde allied with the invading Orcish Horde, hoping to spare his kingdom. The Alliance of Lordaeron uncovered his treason and struck swiftly. Its forces invaded Alterac City, dismantled its defenses, and placed the kingdom under martial law.",al={"why is alterac in ruins","what happened to alterac city","fall of alterac"},it="ruin"},{q="Who lives in the ruins now?",a="The Crushridge ogres, led by Mug'thol, have overtaken the palace, walls, and snowed-in courtyards. Bro'kin, an enterprising goblin alchemy vendor, sits quietly atop the northern ramparts.",al={"who controls alterac ruins","alterac ogres","who is in alterac"},it="residents"},{q="What is the Syndicate's connection to this place?",a="The Syndicate is made up largely of former Alteraci aristocracy and soldiers who lost their lands when the kingdom was dissolved. They bitterly long to reclaim Alterac, but the Crushridge ogres drove them from the capital. Now they operate from outposts like Strahnbrad.",al={"does the syndicate live here","syndicate alterac connection"},it="ties"},{q="Why do Alliance adventurers come here?",a="Alliance soldiers from Southshore offer bounties on the hostile Crushridge ogres, who raid the roads. Nobles in the south, including Count Remington Ridgewell, also send agents into the ruins to recover lost family heirlooms like the Perenolde Tiara.",al={"alliance quests alterac ruins","crushridge bounty"},it="motive"},{q="Why is the Horde interested in these ruins?",a="Lady Sylvanas Windrunner and the Forsaken take an active interest in artifacts scattered across the fallen human kingdom. They send champions into the ogre-infested stronghold to secure relics of power such as the Crown of Will.",al={"horde quests alterac ruins","sylvanas alterac"},it="purpose"},{q="What is the Ruins of Alterac?",a="These snowbound stone walls and broken parapets are all that remain of Alterac City, once the proud mountain capital of the human Kingdom of Alterac. Founded thousands of years ago following the expansion of Arathor, the city guarded the vital trade routes winding through the mountains until its king's treachery brought about its downfall during the Second War.",al={"what is ruins of alterac","ruins of alterac overview","alterac city"},it="place",add="46d22466"},{q="What happened to Alterac City during the Second War?",a="During the Second War, King Aiden Perenolde struck a clandestine pact with the invading Orcish Horde to spare his realm. When the Alliance of Lordaeron discovered Alterac's treason, Alliance forces marched upon the mountain kingdom, razing the capital and placing the remnants under martial law. Deposed and disgraced, Perenolde was imprisoned, leaving the kingdom shattered and abandoned.",al={"alterac city history","what happened at alterac","fall of alterac"},it="history",add="967fd086"},{q="How dangerous are the Ruins of Alterac?",a="Extremely dangerous for the unprepared. The Crushridge ogres have made the snow-covered streets and dilapidated halls their home, fiercely defending their territory against any who trespass. Compounding the peril, the ruins occasionally draw the attention of the ruthless Syndicate and wandering undead, leaving the mountain passes treacherous and fraught with ambush.",al={"is ruins of alterac dangerous","ruins of alterac threats","alterac city dangers"},it="danger",add="fd0078c8"},{q="Why is this place called the Ruins of Alterac?",a="The site takes its name from the ancient human kingdom and city of Alterac that once stood here. Following the kingdom's dissolution and the physical devastation wrought during the Second War, nothing survived of the grand capital except cracked masonry, shattered gates, and crumbling towers, reducing the once-mighty seat of power to a mere ruined landmark.",al={"why called ruins of alterac","ruins of alterac name origin"},it="name",add="fbcb07c6"}},ang={["race:Human"]="As a human of the Alliance, these ruins recall human weakness and treason during the Second War. Perenolde's cowardice broke the brotherhood of the Seven Kingdoms.",["faction:Horde"]="As a member of the Horde, you hear echoes of the Old Horde's former alliances in this fallen city. The Forsaken can scavenge magical relics while the Crushridge ogres are distracted."},kw={"alterac city","bro'kin","crushridge","mug'thol","perenolde","ruins of alterac","strahnbrad","syndicate"},rel={"topic:alterac-kingdom","topic:syndicate","zone:alterac","subzone:strahnbrad","quest:543","topic:alliance-of-lordaeron","topic:terenas-menethil-ii","topic:second-war"},src={"Ruins of Alterac"}}
E["subzone:uplands"] = {t="subzone",n="Uplands",z="alterac",s="In the northeastern Alterac Mountains, the Syndicate holds the Uplands and its camps. These hills once fed Alterac's mountain fortresses, but now shelter the band's strongest base.",h="In the northeastern Alterac Mountains, the Syndicate holds the Uplands and its camps.",sec={{t="Breadbasket to Bandit Stronghold",b="Before the Second War broke Alterac apart, grain and livestock from the Uplands fed its mountain fortresses. When the kingdom fell into ruin, honest folk left their farms behind. Dispossessed nobles and cutthroats formed the Syndicate, set on taking back what they believed was stolen from them by force. Its camps, patrols, and outposts now fill the hills. Dandred's Fold lies along the western borders.",sp=0},{t="A Seat of Shadows",b="The Syndicate keeps its strongest forces in the Uplands. There, high-ranking conspirators oversee its operations, including Baron Vardus, who is aligned with the shadowy leaders guiding Alterac's remaining nobility. From these hills they direct brigands, raid neighboring valleys, and resist both the Alliance and Horde. Travelers on the northeastern ridges meet entrenched highwaymen who claim the range as their sovereign soil.",sp=0}},faq={{q="What was the Uplands originally used for?",a="The Uplands once fed Alterac's mountain fortresses with grain and livestock. It was the kingdom's main agricultural region before war and betrayal brought its downfall.",al={"uplands history","what used to be here","uplands purpose"},it="history"},{q="Who controls the Uplands now?",a="The Syndicate controls the Uplands. Alterac's former nobles and their bandit network have built several camps here, where their forces are strongest.",al={"who lives in uplands","who holds the uplands","uplands factions"},it="residents"},{q="Where is the Uplands located?",a="The Uplands lies in the northeastern highlands of the Alterac Mountains. Dandred's Fold sits along its western edge.",al={"uplands location","where is uplands","how to find uplands"},it="place"},{q="Who is Baron Vardus?",a="Baron Vardus is an influential Syndicate noble who oversees operations in the Uplands. He directs bandits and conspirators seeking to reclaim Alterac.",al={"baron vardus lore","who is vardus","uplands baron"}},{q="Why is the Uplands ruined and abandoned?",a="The Uplands once flourished as the breadbasket of the kingdom of Alterac, filled with fertile fields and homesteads. When the kingdom collapsed following its betrayal during the Second War, its heartland was shattered. Without the kingdom's protection, the agricultural heart of the region withered and was overrun by criminals, leaving ruins like Dandred's Fold in its wake.",al={"why is uplands ruined","what happened to uplands farms","why is uplands abandoned"},it="ruin",add="35db727f"},{q="Is the Uplands dangerous?",a="It is exceptionally dangerous. The Uplands serves as the primary stronghold of the Syndicate, harboring their heaviest concentration of fighters anywhere in the mountains. Wandering bandits, outlaws, and rogue nobles patrol the hills, fiercely guarding their camps against any outsiders who intrude on their territory.",al={"is uplands dangerous","uplands danger","how dangerous is uplands"},it="danger",add="4211f63f"}},ang={["class:Rogue"]="As a rogue, you can see how displaced nobles organized the Syndicate's bandit network into a lethal force.",["race:Human"]="As a human, you see Alterac's fall in these hills. Once they fed a flourishing kingdom; now cutthroats and ruined ambitions hold them."},kw={"alterac","baron vardus","breadbasket","dandred's fold","mountains","syndicate","uplands"},rel={"zone:alterac","topic:syndicate","topic:alterac-kingdom","subzone:dandred-s-fold"},src={"Uplands"}}
E["zone:alterac"] = {t="zone",n="Alterac Mountains",z="alterac",s="Across the Alterac Mountains, ruined peaks shelter ogres, outlaws, and the remnants of arcane power. Once home to the human kingdom of Alterac and Dalaran’s scholarly magocracy, these highlands draw travelers from nearby foothill settlements and the rebuilding city.",h="Across the Alterac Mountains, ruined peaks shelter ogres, outlaws, and the remnants of arcane power.",sec={{t="The Fallen Kingdom",b="During the Second War, Alterac stood among humanity’s Seven Kingdoms. King Aiden Perenolde betrayed the Alliance of Lordaeron and joined the Old Horde, hoping to save his realm. His treachery was uncovered and crushed, and the kingdom broke into disputed borderlands. After Alterac dissolved, the Third War brought fresh horrors. Its grand stone capital now lies in ruins.\n\nThe Crushridge ogres occupy the Ruins of Alterac under Mug'thol’s leadership. Alterac’s surviving human nobles formed the Syndicate, a vicious band of criminals. They fight by force to reclaim their lost estates.",sp=0},{t="The Rebuilding City",b="On the mountains’ western edge, Dalaran’s surviving magi rebuild beside lordamere lake. The demon lord Archimonde devastated the great city-state during the Third War. Its magi raised a massive, opaque violet dome over the ruins, but the shield has since been removed. The kirin tor now rebuild their sanctum in the open. Archmage Ansirem Runeweaver can be found inside the Violet Citadel.",sp=0},{t="Frontiers of Conflict",b="Southshore and Tarren Mill are staging grounds for journeys into the peaks. Yeti, mountain lions, and Syndicate footpads roam here. Beneath the snow line, a greater conflict churns.\n\nDeep in the mountain passes, the dwarven Stormpike Guard and the reclusive Frostwolf clan of orcs contest Alterac Valley. They fight over ancient territorial and mining rights.",sp=0}},faq={{q="What happened to the Kingdom of Alterac?",a="During the Second War, King Aiden Perenolde betrayed the Alliance to aid the Horde. Lordaeron and Stromgarde crushed the treason and occupied the land. When the Scourge swept through Lordaeron in the Third War, Alterac fell into anarchy, and Crushridge ogres took its ruined capital.",al={"why is alterac destroyed","what happened to perenolde","alterac kingdom lore"}},{q="Who are the Syndicate?",a="The Syndicate is an outlaw band formed from Alterac’s dispossessed nobility. Former Alteraci royals such as Lord Aliden Perenolde lead it. Cutthroats, highwaymen, and disgraced lords terrorize the surrounding lands and drive out rivals as they fight to reclaim their ancestral domains.",al={"who is the syndicate","why are there human bandits in alterac","syndicate lore"}},{q="What happened to Dalaran's glowing dome?",a="After Archimonde devastated Dalaran during the Third War, the surviving Kirin Tor raised a protective magical shield over the ruins. The shield has since been removed, and the city is rebuilding in the open. Archmage Ansirem Runeweaver can be found in the Violet Citadel.",al={"purple dome alterac","what is the violet bubble","dalaran shield"}},{q="Where can I find flight paths or safe inns in Alterac?",a="Southshore and Tarren Mill in the Hillsbrad Foothills are the usual staging grounds for journeys into the snowy peaks. Dalaran on the western edge is open to Alliance travelers as the Kirin Tor rebuild it, though it has no flight master. The Horde is hated by the Kirin Tor and attacked on sight in the city.",al={"alterac flight path","alterac inn","alterac quest hub"}},{q="What is Alterac Valley?",a="Alterac Valley is an isolated, snowy vale contested by the dwarven Stormpike Guard and the Frostwolf clan of orcs. The Stormpikes came on an archaeological expedition, provoking an all-out territorial war with the Frostwolves. The Frostwolves had lived peacefully in the valley since their exile in the First War.",al={"av entrance","frostwolf vs stormpike","where is alterac valley"}},{q="What is Ravenholdt Manor?",a="Ravenholdt Manor lies hidden in an obscure mountain fold east of the main road. Lord Jorach Ravenholdt commands the secretive guildhall of the League of Assassins, a training ground and haven for skilled rogues from across Azeroth.",al={"where is ravenholdt","assassins manor alterac","thieves guild alterac"}}},ang={["class:Rogue"]="As a rogue, you can find Ravenholdt Manor hidden in Alterac’s eastern cliffs. Lord Jorach Ravenholdt watches over elite contracts, lockpicking drills, and the guild’s secrets.",["class:Mage"]="As a mage, you can walk Dalaran’s rebuilding streets, where arcane currents linger and Kirin Tor mages work. The city remains the devastated heart of human spellcraft.",["faction:Alliance"]="As an Alliance traveler, you face Crushridge ogres and Syndicate outlaws in the former kingdom.",["faction:Horde"]="As a member of the Horde, you can find the Frostwolf clan at home in the secluded mountains. Forsaken agents out of Tarren Mill confront ogres and Syndicate outlaws.",["profession:Herbalism"]="As a herbalist, you can find Wintersbite in Alterac’s frozen crags, its only natural habitat. The herb is an essential component in potent cold-weather concoctions."},kw={"alterac","crushridge","dalaran","perenolde","ravenholdt","strahnbrad","syndicate","uplands"},rel={"subzone:ruins-of-alterac","subzone:strahnbrad","subzone:ravenholdt-manor","topic:alterac-kingdom","topic:syndicate","zone:hillsbrad","npc:lord-jorach-ravenholdt"},src={"Alterac Mountains (Classic)","Alterac Mountains"}}
